import scala.io.StdIn.{readLine,readInt}
import scala.collection.mutable.ListBuffer
import scala.language.postfixOps

object Main {
  var cnt = 0

  def merge(a:Array[Int],left:Int,mid:Int,right:Int) = {
    val n1 = mid-left
    val n2 = right-mid
//    val l = a.slice(left,left+n1) :+ Int.MaxValue
    val l = for(k<-left to left+n1 iterator) yield {
      if(k==left+n1) Int.MaxValue
      else a(k)
    }
    val r = a.slice(mid,mid+n2) :+ Int.MaxValue
    var j=0
    var lval = l.next
    for(k<-left until right) {
      if(lval<=r(j)){
        a(k) = lval
        lval = l.next
      } else  {
        a(k)=r(j)
        j += 1
      }
      cnt += 1
    }
  }

  def sort(n:Int,l:List[(Int,Int)]):List[(Int,Int)] = {
    var l2 = l.to[ListBuffer]
    var n2 = n
    while(n2>1) {
      val newl = new ListBuffer[(Int,Int)]
      for(i<-l2) {
        val mid = (i._2+i._1)/2
        newl ++= List((i._1,mid),(mid,i._2))
      }
      l2 = newl.to[ListBuffer]
      n2 = n2/2
    }
    l2.toList
  }

  def mergeSort(l:List[(Int,Int)],a:Array[Int]):Unit = {
    if(l.length==1) return
    else {
      var i = 0
      var left = 0
      var right = 0
      val b = new ListBuffer[(Int,Int)]
      for(e<-l) {
          val mid = (e._2+e._1)/2
          if(e._2-e._1>1)
            merge(a,e._1,mid,e._2)
          if(i==1) {
            right = e._2
            b += ((left,right))
            i = 0
          } else {
            left = e._1
            i+=1
          }
      }
      mergeSort(b.toList,a)
    }
  }

  def main(args:Array[String]) = {
    val n = readInt
    val a = readLine.split(" ").map(_.toInt)
    val r = sort(n/2,List((0,n/2),(n/2,n)))
    mergeSort(r,a)
    merge(a,0,n/2,n)
    println(a.mkString(" "))
    println(cnt)
  }
}

