  val cnt = MergeSort.sort(xs)

  println(xs.mkString(" "))
  println(cnt)
}

object MergeSort {
  val Max: Int      = 500000
  val Sentinel: Int = 2000000000

  def sort(xs: Array[Int]): Int = {

    val ls = new Array[Int](Max / 2 + 2)
    val rs = new Array[Int](Max / 2 + 2)

    def mergeSort(left: Int, right: Int): Int = {
      val m = right - left
      if (m <= 1) 0
      else {
        val mid  = (left + right) / 2
        val cnt1 = mergeSort(left, mid)
        val cnt2 = mergeSort(mid, right)
        merge(left, mid, right)
        cnt1 + cnt2 + m
      }
    }

    def merge(left: Int, mid: Int, right: Int): Unit = {
      val n1 = mid - left
      val n2 = right - mid
      Array.copy(xs, left, ls, 0, n1)
      Array.copy(xs, mid, rs, 0, n2)
      ls(n1) = Sentinel
      rs(n2) = Sentinel
      var i  = 0
      var j  = 0
      var k  = left
      while (k < right) {
        if (ls(i) <= rs(j)) {
          xs(k) = ls(i)
          i += 1
        } else {
          xs(k) = rs(j)
          j += 1
        }
        k += 1
      }
    }

    mergeSort(0, xs.length)
  }
}

import scala.io.StdIn.{readInt, readLine};

object Main {
    def main(args: Array[String]): Unit = {
        val n = readInt;
        val arr = readLine.split(" ").map(_.toLong);
        val cnt = mergeSort(arr, n);
        println(arr.mkString(" "));
        println(cnt);

    }
    def mergeSort(arr: Array[Long], n: Int): Int = {
        def _mergeSort(first: Int, last: Int): Int = {
            if (last - first > 0) {
                val pivot = (first + last) / 2;
                val cnt1 = _mergeSort(first, pivot);
                val cnt2 = _mergeSort(pivot + 1, last);
                val cnt3 = merge(arr, first, last, pivot);
                cnt1 + cnt2 + cnt3;
            } else {
                0;
            }
        }
        _mergeSort(0, n - 1);
    }

    def merge(arr: Array[Long], first: Int, last: Int, pivot: Int): Int = {
        val tmpArr = (first to pivot).map(arr(_)).toArray;
        var ptr1 = 0;
        var ptr2 = pivot + 1;
        var cnt = 0
        for (i <- (first to last)) {
            cnt += 1;
            if (ptr1 >= tmpArr.length) {
                arr(i) = arr(ptr2);
                ptr2 += 1;
            } else if (ptr2 > last) {
                arr(i) = tmpArr(ptr1);
                ptr1 += 1;
            } else {
                if (arr(ptr2) < tmpArr(ptr1)) {
                    arr(i) = arr(ptr2);
                    ptr2 += 1;
                } else {
                    arr(i) = tmpArr(ptr1);
                    ptr1 += 1;
                }
            }
        }
        cnt;
    }
}

