    val n1 = mid-left
    val n2 = right-mid
    val ll = for(i<-left to mid iterator) yield {
      val x = if(i<mid) a(i) else Int.MaxValue; x
    }
    val rl = for(i<-mid to right iterator) yield {
      val x = if(i<right) a(i) else Int.MaxValue; x
    }
    var i=0
    var j=0
    var l = ll.next
    var r = rl.next
    for(k<-left until right) {
      if(l<=r){
        a(k) = l
        if(ll.hasNext) l = ll.next
      } else  {
        a(k)=r
        if(rl.hasNext) r = rl.next
      }
      cnt += 1
    }
  }

  def sort(n:Int):Iterator[(Int,Int)] = {
