object Main {
  def merge(a: Array[Int], left: Int, mid: Int, right: Int) = {
    val l = new Array[Int](mid-left+1)
    val r = new Array[Int](right-mid+1)
    Array.copy(a,left,l,0,l.length-1)
    Array.copy(a,mid,r,0,r.length-1)
    l(mid-left) = Int.MaxValue
    r(right-mid) = Int.MaxValue

    def loop(a: Array[Int], i: Int, j: Int, k: Int, cnt: Int):Int = {
      if(k==right) cnt
      else if( l(i) <= r(j) ) {
        a(k) = l(i)
        loop(a, i+1, j, k+1, cnt+1)
      } else {
        a(k) = r(j)
        loop(a, i, j+1, k+1, cnt+1)
      }
    }
    loop(a, 0, 0, left, 0)
  }

  def mergeSort(a: Array[Int], left: Int, right: Int):Int = {
    if(left+1<right) {
      val mid = (left + right) / 2
      val x = mergeSort(a, left, mid)
      val y = mergeSort(a, mid, right)
      x + y + merge(a,left,mid,right)
    } else 0
  }

  def main(args:Array[String]) = {
    val n = readInt
    val a = readLine.split(" ").map(_.toInt)
    val cnt = mergeSort(a,0,a.length)
    println(a.mkString(" "))
