object MergeSort extends App {

  val SENTINEL = 10000000001L

  def sliceAndTerminate(a: Array[Long], from: Int, until: Int) = {
    val n = until - from
    val ret = new Array[Long](n + 1)
    compat.Platform.arraycopy(a, from, ret, 0, n)
    ret(n) = SENTINEL
    ret
  }

  def merge(a: Array[Long], left: Int, mid: Int, right: Int) = {
    val l = sliceAndTerminate(a, left, mid)
    val r = sliceAndTerminate(a, mid, right)

    def loop(i: Int, j: Int, k: Int): Unit = {
      if (k < right) {
        if (l(i) <= r(j)) {
          a(k) = l(i)
          loop(i+1, j, k+1)
        } else {
          a(k) = r(j)
          loop(i, j+1, k+1)
        }
      }
    }

    loop(0, 0, left)
    right - left
  }

  def mergeSort(a: Array[Long], left: Int, right: Int): Int = {
    if (left + 1 < right) {
      val mid = (left + right) / 2
      mergeSort(a, left, mid) +
      mergeSort(a, mid, right) +
      merge(a, left, mid, right)
    } else 0
  }


  val sc = new java.util.Scanner(Console.in)

  def readInt() = sc.next().toInt
  def readLong() = sc.next().toLong

  val ary = Array.fill(readInt())(readLong())
  val n = mergeSort(ary, 0, ary.length)
  println(ary mkString " ")
  println(n)
}

