int merge(	std::vector<int>::iterator left,
			std::vector<int>::iterator mid, 
			std::vector<int>::iterator right){
	int cnt = 0;
	std::vector<int> L,R;

	for(std::vector<int>::iterator i=left; i!=mid; i++) L.push_back(*i);
	L.push_back(1000000000);
	for(std::vector<int>::iterator i=mid; i!=right; i++) R.push_back(*i);
