	std::vector<int>::iterator ri = R.begin();
	std::vector<int>::iterator li = L.begin();

	for(std::vector<int>::iterator k=left; k!=right; k++){
		if(*li>*ri){
			*k = *ri;
			ri += 1;
		}else{
			*k = *li;
			li += 1;
		}
		cnt += 1;
	}
	return cnt;
}

