void my_merge(std::vector<int>& A, int left, int mid, int right){
    int n1 = mid - left;
    int n2 = right - mid;

    // create array L[0...n1], R[0...n2]
    std::vector<int> L(n1+1), R(n2+1);
    for(int i = 0; i < n1; i++){
	L.at(i) = A.at(left + i);
    }
    for(int i = 0; i < n2; i++){
	R.at(i) = A.at(mid + i);
    }
    const int SENTINEL = 1000000002;
