    for(int k = left; k < right; k++){
	compare_times++;
	if(L.at(i) <= R.at(j)){
	    A.at(k) = L.at(i);
	    i = i + 1;
	}else{
	    A.at(k) = R.at(j);
	    j = j + 1;
	}
    }
}

