    for( int i = left; i < right; ++i ) {
        if( a[t1] < b[t2] ) {
            dt[i] = a[t1];
            t1++;
        }
        else {
            dt[i] = b[t2];
            t2++;
        }
        ++ans;
    }
}

void marge_sort( int dt[], int left, int right ) {
    if( right - left > 1 ) {
        int mid = right + left >> 1;
        marge_sort( dt, left, mid );
        marge_sort( dt, mid, right );
        marge( dt, left, mid, right );
    }
}

