            vec_right[i] = vec[mid + 1 + i];
        }

        int i = 0, j = 0, k = left;
        while (i < left_size && j < right_size) {
            if (vec_left[i] < vec_right[j]) {
                vec[k] = vec_left[i];
                ++i;
                ++k;
            } else {
                vec[k] = vec_right[j];
                ++j;
                ++k;
            }
            ++count;
        }

        while (i < left_size) {
            ++count;
            vec[k] = vec_left[i];
            ++i;
            ++k;
        }

        while (j < right_size) {
            ++count;
            vec[k] = vec_right[j];
            ++j;
            ++k;
        }
    }
}

