using namespace std;

namespace {

static int Merge(int* A, int left, int mid, int right) {
  const int n1 = mid - left;
  const int n2 = right - mid;

  // When sorting large arrays, allocating L and R in heap for
  // each Merge call makes a bit the program slower.
  //
  // In the real application, we should use std::vectors instead of
  // fixed sized arrays, though.
  // vector<int> L(n1+1, 0);
  // vector<int> R(n2+1, 0);
  int L[n1 + 1];
  int R[n2 + 1];

  for (int i = 0; i < n1; ++i) {
    L[i] = A[left + i];
  }
  for (int i = 0; i < n2; ++i) {
    R[i] = A[mid + i];
  }

  static const int kInf = numeric_limits<int>::max();
  L[n1] = kInf;
  R[n2] = kInf;

  int i = 0;
  int j = 0;
  for (int k = left; k < right; ++k) {
    if (L[i] <= R[j]) {
      A[k] = L[i];
      i++;
    } else {
      A[k] = R[j];
      j++;
    }
  }
  return right - left;
}

static int MergeSortInternal(int* A, int left, int right) {
  if (left + 1 >= right) return 0;

  const int mid = (left + right) / 2;
  return MergeSortInternal(A, left, mid) + MergeSortInternal(A, mid, right) +
         Merge(A, left, mid, right);
}

static int MergeSort(int* A, int n) { return MergeSortInternal(A, 0, n); }
}  // namespace

