int mergesort(int* A,int left,int right)
{
	int mid,sol = 0;

	while(left < right)
	{
		mid = (left + right) / 2;
		mergesort(A,left,mid);
		mergesort(A,mid,right);
		sol += merge(A,left,mid,right);
	}

	return sol;
}

