int merge(vector<int> &as, int l, int mid, int r) {
    const auto n1  = mid - l;
    const auto n2  = r - mid;
    const auto lim = numeric_limits<int>::max();
    vector<int> L(n1 + 1);
    rep(i, 0, n1) {
        L[i] = as[l + i];
    }
    L[n1] = lim;
    vector<int> R(n2 + 1);
    rep(i, 0, n2) {
        R[i] = as[mid + i];
    }
    R[n2] = lim;
    int i = 0, j = 0;
    rep(k, l, r) {
        if (L[i] <= R[j]) {
            as[k] = L[i];
            i++;
        } else {
            as[k] = R[j];
            j++;
        }
    }
    return r - l;
}

int merge_sort(vector<int> &as, int l, int r) {
    if (abs(l - r) <= 1) return 0;

    auto mid = (l + r) / 2;
    int res  = 0;
    res += merge_sort(as, l, mid);
    res += merge_sort(as, mid, r);
    res += merge(as, l, mid, r);
    return res;
}

