void merge(int a[], int left, int mid, int right)
{	
	int n1 = mid - left + 1;
	int n2 = right - (mid + 1) + 1;
	int *l = new int[n1 + 1];
	int *r = new int[n2 + 1];
	for (int i = 0; i <= n1; i++) l[i] = a[left + i];
	for (int i = 0; i <= n2; i++) r[i] = a[(mid + 1) + i];
	l[n1] = 9999;
	r[n2] = 9999;

	int i = 0, j = 0;
