int cnt = 0;

void MergeSort(vector<int> &A, int left, int right) {
    if (right - left == 1)
        return;
    int mid = (right + left) / 2;

    MergeSort(A, left, mid);
    MergeSort(A, mid, right);

    vector<int> buf;
    for (int i = left; i < mid; i++) {
        buf.push_back(A[i]);
    }

    // 逆順でコピー
    for (int i = right - 1; i >= mid; i--) {
        buf.push_back(A[i]);
    }

    //統合
    int itrl = 0;
    int itrr = buf.size() - 1;
    for (int i = left; i < right; i++) {
        if (buf[itrl] <= buf[itrr]) {
            A[i] = buf[itrl];
            itrl++;
        } else {
            A[i] = buf[itrr];
            itrr--;
        }
        cnt++;
    }
}

