    int N;
    cin >> N;
    vector<int> A(N);
    rep(i, N) { cin >> A[i]; }

    MergeSort(A, 0, N);
    rep(i, N - 1) { cout << A[i] << " "; }
    cout << A[N - 1] << endl;
    cout << cnt << endl;
}

