vector<int> tmp;
void mer(vector<int> &data, int l, int m, int r){
	for (int i = l; i < r; ++i) tmp[i] = data[i];

	int p1(l), p2(m);
	while (p1 < m && p2 < r) {
		if (tmp[p1] <= tmp[p2]) data[l++] = tmp[p1++];
		else data[l++] = tmp[p2++];
	}
	while (p1 < m) data[l++] = tmp[p1++];
	while (p2 < r) data[l++] = tmp[p2++];
	cnt += (r - l);
}

void merS(vector<int> &data, int l, int r){
	if (l + 1 < r){
		int m = l + (r - l) / 2;
		merS(data, l, m);
		merS(data, m, r);
		mer(data, l, m, r);
	}
}

