  /* left から mid*/
  for(i=left;i<=mid;i++)
    temp[i]=A[i];

  /* mid + 1からright */
  for(i=mid+1,j=right;i<=right;i++,j--)
    temp[i]=A[j];

  i=left;         
  j=right;       

  for(k=left;k<=right;k++){    
    if(temp[i]<=temp[j])      
      A[k]=temp[i++];

    else
      A[k]=temp[j--];

    count++;
  }
}

