int merge(std::vector<int> &a, int left, int mid, int right) {
  int nL = mid - left, nR = right - mid;
  std::vector<int> L(nL + 1, INF), R(nR + 1, INF);
  for (int i = 0; i < nL; i++) {
    L[i] = a[left + i];
  }
  for (int i = 0; i < nR; i++) {
    R[i] = a[mid + i];
  }

  int i = 0, j = 0;
  for (int k = left; k < right; ++k) {
    if (L[i] <= R[j]) {
      a[k] = L[i];
      ++i;
    } else {
      a[k] = R[j];
      ++j;
    }
  }
  return i + j;
}

