  unsigned int n;
  std::scanf("%d", &n);
  int ss[n];
  for (auto i = 0u; i < n; ++i) {
    std::scanf("%d", &ss[i]);
  }

  merge_sort(ss, ss+n);

  print_ints(ss, n);
  print_int(comparison_count);

  return 0;
}

