void merge(int* L, int* R, int* array, int left, int mid, int right)
{
    for(int i=left; i<mid; ++i) L[i - left] = array[i];
    for(int i=mid; i<right; ++i) R[i - mid] = array[i];
    int l = 0, r = 0;
