//すでに整列済みの二つの数列からそれらを合わせた数列を整列させる関数
void merge(int A[],int left,int mid,int right){int n1,n2;

	n1 = mid -left;
	n2 = right - mid;
	//n2-n1=right-left

	int L[N_MAX];//n1
	int R[N_MAX];//n2

	for(int i=0;i<n1;i++){
		L[i] = A[left + i];
	}

	for(int i=0;i<n2;i++){
		R[i] = A[mid + i];
	}

	L[n1] = INFTY;
	R[n2] = INFTY;

	int i_L=0;
	int i_R=0;
	for(int k=left;k < right;k++){//整列後の数列のk番目の値を決める
		if(L[i_L] <= R[i_R]){
			A[k] = L[i_L];//昇順なので小さい方が採用される
			i_L++;
		}else{
			A[k] = R[i_R];//昇順なので小さい方が採用される
			i_R++;
		}
		n_cmpr++;
	}
}

