{
	//right是数组最后一个位置的下一个 
	int n1 = mid - left;	//左边元素的个数,不包括mid,从0~mid-1 
	int n2 = right - mid;	//右边元素的个数,mid~right-1

	int L[n1], R[n2];	//将来自上一层的数组一分为二（其中，左右两边分别有序）
	for (int i = 0; i < n1; i++) {
		L[i] = arr[left+i];	
