{
	v L(m - l);
	copy(l, m, L.begin());
	vi cp = L.begin();

	for (vi i = l; i != r; i++)
		if (cp == L.end())
			break;
		else if (m == r) {
			copy(cp, L.end(), i);
			break;
		} else if(*cp <= *m)
			*i = *cp, cp++;
		else
			*i = *m, m++;
}

