void merge(int A[], int l, int m, int r){
    int n1 = m-l+1;
    int n2 = r-m;
    int *B = (int *)calloc(n1+1, sizeof(int));
    int *C = (int *)calloc(n2+1, sizeof(int));
    for(int i=0; i<n1; i++){
        B[i] = A[l+i];
    }
    for(int i=0; i<n2; i++){
        C[i] = A[m+1+i];
    }
    B[n1] = INT_MAX;
    C[n2] = INT_MAX;
    int i = 0;
    int j = 0;
    for(int k=0; k<r-l+1; k++){
        if(B[i] < C[j]){
            A[k+l] = B[i];
            i++;
        }else{
            A[k+l] = C[j];
            j++;
        }
    }
}

