void merge_sort_helper(int *A, int n, int l, int m, int r)
{
	for (int i = l; i < r; ++i) tmp[i] = A[i];

	int idx0 = l;
	int idx1 = l;
	int idx2 = m;
	while (idx1 < m && idx2 < r)
	{
		A[idx0++] = (tmp[idx1] <= tmp[idx2]) ? tmp[idx1++] : tmp[idx2++];
		cnt++;
