vector <int> MergeSort(vector <int> &A, int &n){
    int nn = A.size();   int X,Y,Z = 0;
    if(nn < 2)
        return A;
    int mid = nn/2;
    vector <int> I(mid);
    vector <int> II(nn-mid);
    for(int i = 0; i < mid; i++)
        I[i] = A[i];
    for(int i = mid; i < nn; i++)
        II[i-mid] = A[i];
    MergeSort(I,n);
    MergeSort(II,n);
    Merge(A,n,I,II);
    return A;
}
void Merge(vector <int> &A, int &n, vector <int> I, vector <int> II){
    int i,j,k; i = j = 0;
    int nn = A.size();
    for(k = 0; k < nn; k++){
        n++;
        if(II[j] < I[i]){
            A[k] = II[j];
            j++;
        }else{
            A[k] = I[i];
            i++;
        }
    }
}

