void merge(int *A, int left, int mid, int right) {
    int n1 = mid - left; // left の添え字が0 mid-1 がn1-1
    int n2 = right - mid; // mid の添え字が0 right -1 がn2-1
    for (int i = 0; i < n1; i++) {
        L[i] = A[left + i];
    }
    for (int i = 0; i < n2; i++) {
        R[i] = A[mid + i];
    }
    L[n1] = INFTY;
    R[n2] = INFTY;
    int i = 0, j = 0;
