void merg(int s,int e){
    int mid=(s+e)/2;
    int s1=s;
    int e1=mid+1;
    int *ar=new int(e-s+1);
    int cnt=0;
    while(s1<=mid&&e1<=e){
        if(a[s1]<=a[e1]){
            ar[cnt++]=a[s1++];
        }else{
            ar[cnt++]=a[e1++];
        }
        num++;
    }
    while(s1<=mid){ar[cnt++]=a[s1++];num++;}
    while(e1<=e){ar[cnt++]=a[e1++];num++;}
    int i;
    for(i=0;i<e-s+1;i++){
        a[s+i]=ar[i];
    }
}

