typedef vector<int> V;

int merge(V &s, int left, int mid, int right) {
    int n1 = mid - left;
    int n2 = right - mid;
    V l = V(n1);
    V r = V(n2);
    for (int i = 0; i < n1; i++) {
        l[i] = s[left + i];
    }
    for (int i = 0; i < n2; i++) {
        r[i] = s[mid + i];
    }
    int i = 0, j = 0, c = 0;
    for (int k = left; k < right; k++) {
        if (j >= r.size() || (i < l.size() && l[i] <= r[j])) {
            s[k] = l[i++];
        } else {
            s[k] = r[j++];
        }
        c++;
    }
    return c;
}

