template<typename T> size_t merge(vector<Ty>& A, int left, int mid, int right) {
	size_t numCmp = 0;
	int n1 = mid - left;
	int n2 = right - mid;
	vector<T> L(n1 + 1), R(n2 + 1);
	for (int i = 0; i < n1; i++)
		L[i] = A[left + 1];
	for (int i = 0; i < n2; i++)
		R[i] = A[mid + 1];
	L[n1] = R[n2] = numeric_limits<T>::max();
	int i = 0, j = 0;
	for (int k = left; k < right; k++) {
		numCmp++;
		if (L[i] <= R[j]) {
			A[k] = L[i];
			i++;
		}
		else {
			A[k] = R[j];
			j++;
		}
	}
	return numCmp;
}

template<typename T> size_t mergeSort(vector<T>& A, int left, int right) {
	size_t numCmp = 0;
	if (left + 1 < right) {
		int mid = (left + right) / 2;
		numCmp += mergeSort(A, left, mid);
		numCmp += mergeSort(A, mid, right);
		numCmp += merge(A, left, mid, right);
	}
	return numCmp;
}

