void merge(int A[], int n, int left, int mid, int right, int &ans) {
    int *tmp = new int[n];

    for (int i = left; i <= mid; ++i) {
        tmp[i] = A[i];
    }

    for (int i = mid + 1, j = right; i <= right; --j, ++i) {
        tmp[i] = A[j];
    }

    int i = left;
    int j = right;
    for (int k = left; k <= right; ++k) {
        ++ans;
        if (tmp[i] <= tmp[j]) {
            A[k] = tmp[i++];
        } else {
            A[k] = tmp[j--];
        }
    }

    delete[] tmp;
}

