#include <stdio.h>

#define N 1000000000
int count=0;
int temp[N];    

void MergeSort(int *,int,int);

/* left から right マージソート */
void MergeSort(int *A, int left, int right)
{
  int mid,i,j,k;
   /* 配列の要素が一つの場合 */
  if (left>=right)             
    return;                     


  mid=(left+right)/2;      
  MergeSort(A,left,mid);       
  MergeSort(A,mid+1,right);  

  /* left から mid*/
  for(i=left;i<=mid;i++)
    temp[i]=A[i];

  /* mid + 1からright */
  for(i=mid+1,j=right;i<=right;i++,j--)
    temp[i]=A[j];

  i=left;         
  j=right;       

  for(k=left;k<=right;k++){    
    if(temp[i]<=temp[j])      
      A[k]=temp[i++];

    else
      A[k]=temp[j--];

    count++;
  }
}
