void merge_sort(size_t i, size_t j) {
  if (j - i <= 1)
    return;
  size_t k = (i + j) / 2;
  merge_sort(i, k);
  merge_sort(k, j);
  std::copy(S + i, S + k, L);
  std::copy(S + k, S + j, R);
  c += j - i;
  for (size_t l = i, p = 0, q = 0;; l++) {
    if (p < k - i && q < j - k) {
      if (L[p] <= R[q])
        S[l] = L[p++];
      else
        S[l] = R[q++];
    } else if (p < k - i)
      S[l]= L[p++];
    else if (q < j - k)
      S[l] = R[q++];
    else
      break;
  }
}

