queue<int> mergeSort(queue<int> q){
    if(q.size() == 1) return q;
    queue<int> left,right,a,b;
    int size = q.size();
    for(int i =0; i < size; ++i){
        if(i < size/2){
            left.push(q.front());
            q.pop();
        }
        else{
            right.push(q.front());
            q.pop();
        }
    }
    a = mergeSort(left);
    b = mergeSort(right);
    return merge(a,b);
}
