  auto ret=0u;
  auto out=result;
  for(auto in1=first,in2=mid; ; ++out,++ret){
    if(in1==mid){
      ret+=last-in2;
      for(; in2!=last; ++in2,++out) *out=*in2;
      break;
    }
    if(in2==last){
      ret+=mid-in1;
      for(; in1!=mid; ++in1,++out) *out=*in1;
      break;
    }
    if(*in1<*in2){
      *out=*in1;
      ++in1;
    } else{
      *out=*in2;
      ++in2;
    }
  }
  copy(result, out, first);
