    int n1 = mid - left;
    int n2 = right - mid;
    vector<int> l(n1+1);
    vector<int> r(n2+1);
    for (int i=0; i<n1; ++i){
        l[i] = a[left + i];
    }
    for (int i=0; i<n2; ++i){
        r[i] = a[mid + i];
    }
    l[n1] = INF;
    r[n2] = INF;
    int i = 0;
    int j = 0;
    for (int k=left; k<right; ++k){
        if(l[i] <= r[j]){
            a[k] = l[i];
            i++;
        }
        else {
            a[k] = r[j];
            j++;
        }
        swap_times++;
    }
    return;
}

void mergesort(vector<int> &a, int left, int right){
    if(left + 1 < right){
        int mid = (left + right) / 2;
        mergesort(a, left, mid);
        mergesort(a, mid, right);
        merge(a, left, mid, right);
    }
    return;
}

