int s[500000];

int marge(int left, int right) {
	int count = 0;
	int index = left;
	if (right-1 == left) {
		return 0;
	}
		int mid = (left + right) / 2;
		count += marge(left, mid);
		count += marge(mid, right);
		int i = left;
		int j = mid;
		int t[500000];
		while(i < mid && j < right){
			if (s[i] < s[j]) {
				t[index] = s[i];
				i++;
			} else {
				t[index] = s[j];
				j++;
			}
			index ++;
		}
		while (i == mid && j < right) {
			t[index] = s[j];
			j++;
			index++;
		}
		while(j == right && i < mid) {
			t[index] = s[i];
			i++;
			index++;
		}
		j = left;
		for (int i = left; i < right; i++,j++) {
			s[i] = t[j];
		}
	return count + right - left;
}

