  uint32_t left_index = 0, right_index = 0;
  for (uint32_t i = left; i < right; i++) {
    count++;
    if (lefts[left_index] < rights[right_index]) {
      array[i] = lefts[left_index];
      left_index++;
    } else {
      array[i] = rights[right_index];
      right_index++;
    }
  }

  return count;
}

