{
  uint32_t count = 0;
  if (left + 1 < right) {
    uint32_t mid = (left + right) / 2;
    count += merge_sort(left, mid);
    count += merge_sort(mid, right);
    count += merge(left, mid, right);
  }

  return count;
}

