void merge( int x, int y ){
	if( x == y ) return;
	int c1 = (x + y) / 2;
	int c2 = ((x + y) / 2) + 1;

	merge( x, c1 );
	merge( c2 , y);

	for( int i = 0 ; i <= c1 - x ; i++ ) l[i] = a[i + x];
	for( int i = 0 ; i <= y - c2 ; i++ ) r[i] = a[i + c2];

	l[c1 - x + 1] = inf;
	r[y - c2 + 1] = inf;

	int k = x, l1 = 0, r1 = 0;

	for( int i = 0 ; i < y - x + 1 ; i++ ){
		a[k] = min( l[l1], r[r1]);
		k++;
		if( l[l1] > r[r1] ) r1++;
		else l1++;	
	}
	s += y - x + 1;	

}


