void merge(int A[],int left,int mid,int right){int n1,n2;

	n1 = mid -left;
	n2 = right - mid;
	//n2-n1=right-left

	int L[N_MAX];//n1
	int R[N_MAX];//n2

	for(int i=0;i<n1;i++){
