template<typename T>
auto merge(std::deque<T> xdq, std::deque<T> ydq){
    //for(auto& x:xdq) cout<<x<<" ";cout<<"-- ";
    //for(auto& y:ydq) cout<<y<<" ";cout<<"\t";
    if (xdq.empty()){++cnt; return ydq;}
