    ++cnt;//cout<<cnt<<"\n";
    if (xdq[0] < ydq[0]){
        auto x = xdq[0]; xdq.pop_front();
        auto res = merge(xdq, ydq);
        res.push_front(x);
        return res;
    }else{
        auto y = ydq[0]; ydq.pop_front();
        auto res = merge(xdq, ydq);
        res.push_front(y);
        return res;
    }  
}

template<typename T>
std::deque<T> msort(std::deque<T> dq){
    if(dq.empty()){
        deque<T> res{}; return res;
    }
    if(dq.size()==1) return dq;

    int h = dq.size()/2;
    deque<T> xharf(h); copy(dq.begin(), dq.begin()+h, xharf.begin());
    deque<T> yharf(dq.size()-h); copy(dq.begin()+h,dq.end(), yharf.begin());
    return merge(msort(xharf), msort(yharf));
}

