//mergesort
int merge_sort(const vector<int>::iterator beg, const vector<int>::iterator end){
  if(beg+1 >= end) return 0;

  //divide
  const auto mid = beg+(end-beg)/2;
  int comp_count =
    merge_sort(beg, mid) +
    merge_sort(mid, end);

  //conquer
  vector<int> buff(end - beg);
  auto h1 = beg, h2 = mid;
  for(int& s : buff){
    if(h1 == mid){
      s = *(h2++);
      ++comp_count;
      //++h2;
    }
    else if(h2 == end){
      s = *(h1++);
      ++comp_count;
      //++h1;
    }
    else{
      s = (*h1 <= *h2 ? *(h1++) : *(h2++));
      //s = *h1; h1++;
      ++comp_count;
    }
  }
  auto itr = beg;
  for(auto s : buff){
    //*(itr++) = s;
    *itr = s;
    ++itr;
  }

  return comp_count;
}


