void syf(int *A,int x,int y,int *T){
	if(y-x>1){
		int m=(x+y)/2;
		int i=x,p=x,q=m;
		syf(A,x,m,T);
		syf(A,m,y,T);
		while(p<m||q<y){
			if(q>=y||(p<m&&A[p]<=A[q])) T[i++]=A[p++];
			else T[i++]=A[q++];
			g++;
		}
		for(int i=x;i<y;++i){
			A[i]=T[i];
			AA[i]=T[i];
		}
	}
}
