int MergeSort(vector <int> &A, int &nn){
    int n = A.size();   int X,Y,Z = 0;
    if(n < 2)
        return 0;
    int mid = n/2;
    vector <int> I(mid);
    vector <int> II(n-mid);
    for(int i = 0; i < mid; i++)
        I[i] = A[i];
    for(int i = mid; i < n; i++)
        II[i-mid] = A[i];
    X = MergeSort(I,nn);
    Y = MergeSort(II,nn);
    Z = Merge(A,I,II,nn);
    return X+Y+Z;
}
int Merge(vector <int> &A, vector <int> I, vector <int> II, int &nn){
    int i,j,k; i = j = 0;   int C = 0;
    int n = A.size();
    for(k = 0; k < n; k++){
        nn++;
        if(II[j] < I[i]){
            A[k] = II[j];
            j++;
            C += I.size() - i;
        }else{
            A[k] = I[i];
            i++;
        }
    }
    return C;
}

