void marge(int list[], size_t left, size_t mid, size_t right, size_t len){
	int i = 0;
	int j = 0;
	int k = 0;
	int n_1 = mid - left;
	int n_2 = right - mid;
	int B[right - left];

	while(i < n_1 && j < n_2){
		if(list[i + left] <= list[j + mid]){
			B[k] = list[i + left];
			i ++;
		}else{
			B[k] = list[j + mid];
			j ++;
		}
		k ++;
	}
	if(i == n_1){
		while(j < n_2){
			B[k] = list[j + mid];
			j ++;
			k ++;
		}
	}else{
		while(i < n_1){
			B[k] = list[i + left];
			i ++;
			k ++;
		}
	}
	count += k;

	for(size_t i = 0; i < right - left; i ++){
		list[left + i] = B[i];
	}
}

