int compareCount = 0;

void merge(vector<int> &A, int left, int mid, int right) {
  int n1 = mid - left;
  int n2 = right - mid;

  // L[0...n1], R[0...n2] を生成
  vector <int>L(n1 + 1);
  for (int i = 0; i < n1; i++) {
    L.at(i) = A.at(left + i);
  }
  vector <int>R(n2 + 1);
  for (int i = 0; i < n2; i++) {
    R.at(i) = A.at(mid + i);
  }

  L.at(n1) = INT_MAX;
  R.at(n2) = INT_MAX;
  int i = 0;
  int j = 0;
  for (int k = left; k < right; k++) {
    // 比較回数をカウントする
    compareCount++;

    if (L.at(i) <= R.at(j)) {
      A.at(k) = L.at(i);
      i = i + 1;
    } else {
      A.at(k) = R.at(j);
      j = j + 1;
    }
  }
}

void mergeSort(vector<int> &A, int left, int right) {
  if (left + 1 < right) {
    int mid = (left + right) / 2;
    mergeSort(A, left, mid);
    mergeSort(A, mid, right);
    merge(A, left, mid, right);
  }
}

