void merge(int *A,int left,int  mid,int  right){
  int i,j,k,n1,n2;
  double *L, *R;

  n1 = mid - left;
  n2 = right - mid;
  /* L[0...n1], R[0...n2] を生成 */
  L = (double *)malloc(n1+1);
  R = (double *)malloc(n2+1);

  for(i = 0; i <= n1-1 ; i++) L[i] = A[left + i];
  for (i = 0 ;i <= n2-1 ; i++) R[i] = A[mid + i];
  L[n1] = 1.0/0.0;
  R[n2] = 1.0/0.0;
  i = 0;
  j = 0;
  for (k = left ; k <= right-1 ; k++){
    if (L[i] <= R[j]){
      A[k] = L[i];
      i = i + 1;
      count ++;
    }
    else {
      A[k] = R[j];
      j = j + 1;
      count++;
    }
  }
  free(L);
  free(R);
}

