  int n1 = mid - left;
  int n2 = right - mid;
  int* L = (int*)malloc(n1 * sizeof(int));
  int* R = (int*)malloc(n2 * sizeof(int));
  for(int i=0; i<n1; i++) {
    L[i] = A[left+i];
  }
  for(int i=0; i<n2; i++) {
