template<class Container , class F>
auto merge(Container& arr, ui first, ui mid, ui last,F f) {
//	std::cout << first << " " << last << "\n";
	auto a = mid - first;
	auto b = last - mid;

	std::vector<ui> larr, rarr;
	larr.resize(a+1);
	rarr.resize(b+1);

	for (ui i{}; i < a; ++i) {
		larr[i] = arr[first + i];
//		std::cout << ">> L:" << larr[i]<<"\n";
	}
	for (ui i{}; i < b; ++i) {
		rarr[i] = arr[mid + i];
//		std::cout << ">> R:" << rarr[i] << "\n";
	}

	larr[a] = -1 ;//非負整数の最大値
	rarr[b] = -1 ;//同上

//	for (const auto&e : larr)
//		std::cout << e << " ";
//	std::cout << "\n";

	ui i{}, j{};
	for (ui k{ first }; k < last; ++k) {
		if ( f(larr[i] , rarr[j] ) ){
			arr[k] = larr[i];
			++i;
		}
		else {
			arr[k] = rarr[j];
			++j;
		}
	}
}

