        return A;
    int mid = nn/2;
    vector <int> I(mid);
    vector <int> II(nn-mid);
    for(int i = 0; i < mid; i++)
        I[i] = A[i];
    for(int i = mid; i < nn; i++)
        II[i-mid] = A[i];
    MergeSort(I,n);
