typedef long long ll;

ll merge(int* left, int* mid, int* right) {
  int n1 = mid - left;
  int n2 = right - mid;
  int* L;
  L = new int[n1+1];
  int* R;
  R = new int[n2+1];
  for (auto i = 0; i < n1; i++) {
    L[i] = *(left+i);
  }
  L[n1] = infty;
  for (auto i = 0; i < n2; i++) {
    R[i] = *(mid+i);
  }
  R[n2] = infty;
  int* pl = L;
  int* pr = R;
  for (int* pk = left; pk < right; pk++) {
    if (*pl <= *pr) {
      *pk = *pl;
      pl++;
    } else {
      *pk = *pr;
      pr++;
    }
  }
  delete [] L;
  delete [] R;
  return (ll)(right-left);
}

ll merge_sort(int* left, int* right) {
  ll ans = 0;
  if (left+1 < right) {
    int* mid = left+(right-left)/2;
    ans += merge_sort(left, mid);
    ans += merge_sort(mid, right);
    ans += merge(left, mid, right);
  }
  return ans;
}

