  int count = 0;
  for(int k = left; k < right; k++) {
	if(L[i] <= R[j]) {
      A[k] = L[i];
      i = i + 1;
	  count++;
    }
    else {
      A[k] = R[j];
      j = j + 1;
	  count++;
    }
  }

  return count;
}

