void BubbleSort()
{
  bool flag = true;
  int i = 0;
  SwapNum = 0;

  do
  {

    flag = false;
    for(int j = N - 1; j >= i + 1; --j)
    {
      if(A[j] < A[j-1])
      {
	int tmp = A[j];
	A[j] = A[j-1];
	A[j-1] = tmp;

	flag = true;
	++SwapNum;
      }

    }

    ++i;


  }while(flag);

  return;
}

void SelectionSort()
{

  SwapNum = 0;
  for(int i = 0; i < N; ++i)
  {
    int mini = i;
    bool flag = false;

    for(int j = i; j < N; ++j)
    {
      if(A[j] < A[mini])
      {
	mini = j; 
	flag = true;	
      }
    }

    if(flag)
    {
      int tmp = A[i];
      A[i] = A[mini];
      A[mini] = tmp;

      ++SwapNum; 
    }
  }

  return;

}

void InsertionSort(int g)
{

  for(int i = g; i < N; ++i)
  {
    int v = A[i];
    int j = i - g;

    while( j >= 0 && A[j] > v)
    {
      A[j + g] = A[j];
      j = j - g;
      ++Count;
    }
    A[j + g] = v;
  }

  return;
}

void ShellSort()
{

  Count = 0;

  int m = 0;
  int s = 1;

  while(N / s > 0)
  {
    s *= 2;
    ++m;
  }

  int G[N];

  for(int i = 0, s = 1; i < m; ++i, s *= 2)
    G[i] = N / s; 

  for(int i = 0; i < m; ++i)
    InsertionSort(G[i]);

  cout << m << endl;

  for(int i = 0; i < m; ++i) 
    cout << (i != 0 ? " " : "") << G[i];
  cout << endl;

  cout << Count << endl;

  for(int i = 0; i < N; ++i)
    cout << A[i] << endl;

  return;
}

