int merge(int a[],int temp[],int left,int middle,int right){
    int count = 0;
    int i = left, j = middle ; 
    for(int k = left; k <=right; k++){
        count++;
       //left exists and (right null or <)
       if(i<middle&&(j>right||a[i]<a[j])){
            temp[k] = a[i++];
       }else {
             temp[k]= a[j++];
        }
    }
    //copy back
    for(int k = left; k<=right; k++){
        a[k] = temp[k];
    }
    return count;

}
