int merge(IntVector& A,int left,int mid,int right)
{
	int n1 = mid - left;
	int n2 = right - mid;

	IntVector L;
	L.resize(n1+1);
	for(int i=0;i<n1;i++)
	{
		L[i] = A[left+i];
	}
	IntVector R;
	R.resize(n2+1);
	for(int i=0;i<n2;i++)
	{
		R[i] = A[mid+i];
	}
	L[n1] = INT_MAX;
	R[n2] = INT_MAX;

	int i = 0;
	int j = 0;
	for(int k=left;k<right;k++)
	{
		if(L[i] <= R[j])
		{
			A[k] = L[i];
			i++;
		}else
		{
			A[k] = R[j];
			j++;
		}
	}
