void mergeSort(vector<comparable>& arr, const int& left, const int& right) {
	if (right - left > 1) {
		const int mid = (left + right) / 2;
		mergeSort(arr, left, mid);
		mergeSort(arr, mid, right);
		merge(arr, left, mid, right);
	}
}

