void merge(vector<int> left, vector<int> right, vector<int> &merged_a, int &count) {
    int i = 0, j = 0;
    while (i < left.size() || j < right.size()) {
        if ((i < left.size() && left[i] < right[j]) || j == right.size()) {
            merged_a[i+j] = left[i];
            i++;
            count++;
        } else {
            merged_a[i+j] = right[j];
            j++;
            count++;
        }
    }
}

void merge_sort(vector<int> &a, int &count) {
    if (a.size() > 1) {
        int left_size = a.size() / 2;
        int right_size = a.size() - left_size;
        vector<int> left(left_size);
        vector<int> right(right_size);
        rep(i, left_size) {
            left[i] = a[i];
        }
        rep(i, right_size) {
            right[i] = a[left_size + i];
        }
        merge_sort(left, count);
        merge_sort(right, count);
        merge(left, right, a, count);
    }
}

