using namespace std;
int merge_sort(int arr[], int len){
	int count = 0;
	int* a = arr;
	int* b = (int*) malloc(len*sizeof(int));
	for (int i=1;i<len;i+=i){
		for (int start=0;start<len;start+=i+i){
			int end = min(start+i+i,len);
			int mid = min(start+i,len);
			int s1 = start, s2 = mid;
			int k = start;
			while (s1<mid && s2<end){
				b[k++] = a[s1]<a[s2]? a[s1++]:a[s2++];
				count++;
				}
			while (s1 < mid) {
				count++;
				b[k++] = a[s1++];
			}
			while (s2 < end) {
				count++;
				b[k++] = a[s2++];
			}
		}
		int* t = a;
		a = b;
		b = t;
	}
	if(a!=arr){
		for(int i=0;i<len;i++)
			b[i] = a[i];
		b = a;
	}
	free(b);
	return count;
}

