void msort(int l,int r)
{
	int mid((l+r)>>1);
	if(r-l<=1)
	{
		return;
	}
	msort(l,mid);
	msort(mid,r);
	int p1(mid-1),p2(r-1);
	for(int i=r-1;i>=l;--i)
	{++time;
		if(p1<l)
		{
			exc[i]=arr[p2--];
