// [l,r)
int merge(vector<int>& v, int l, int mid, int r)
{
    vector<int> L(begin(v)+l, begin(v)+mid);
    L.push_back(INF);
    vector<int> R(begin(v)+mid, begin(v)+r);
    R.push_back(INF);

    int i = 0;
    int j = 0;
    FOR(k, l, r) {
        if(L[i] < R[j]) {
            v[k] = L[i];
            ++i;
        }
        else {
            v[k] = R[j];
            ++j;
        }
    }

    return r - l;
}

// [l,r)
int mergesort(vector<int>& v, int l, int r)
{
    if(r-l <= 1) return 0;

    int res = 0;
    int mid = (l+r) / 2;
    res += mergesort(v, l, mid);
    res += mergesort(v, mid, r);
    res += merge(v, l, mid, r);

    return res;
}

void solve()
{
    int ans = mergesort(A, 0, N);

    PRINTLN(A);
    PRINTLN(ans);
}

