void merge_sort(vector<int>& A, int left, int right, int& cnt){
    if (left >= right) return;
    int mid = (left + right) / 2;
    merge_sort(A, left   , mid  , cnt);
    merge_sort(A, mid + 1, right, cnt);
    int A1[mid - left + 2];
    int A2[right - mid + 1];
    for (int i = 0; i < mid - left + 1; i++) {
        A1[i] = A[left+i];
    }
    A1[mid - left + 1] = 1e9 + 1;
    for (int i = 0; i < right - mid; i++) {
