void merge(int a[], int left, int right, int middle)
{
    int const inf = 1e9 + 7;
    int n1 = middle - left;
    int n2 = right - middle;

    int leftarray[n1 + 1], rightarray[n2 + 1];
    for (int i = 0; i < n1; i++)
    {
        leftarray[i] = a[left + i];
    }
    leftarray[n1] = inf;

    for (int i = 0; i < n2; i++)
    {
        rightarray[i] = a[middle + i];
    }
    rightarray[n2] = inf;

    int i = 0, j = 0;
    for (int k = left; k < right; k++)
    {
        counter++;
        if (leftarray[i] <= rightarray[j])
        {
            a[k] = leftarray[i];
            i++;
        }
        else
        {
            a[k] = rightarray[j];
            j++;
        }
    }
}

void my_margesort(int a[], int left, int right)
{
    int middle;
    if (left + 1 < right)
    {
        middle = (left + right) / 2;
        my_margesort(a, left, middle);
        my_margesort(a, middle, right);
        merge(a, left, right, middle);
    }
}

