int merge(vector<int>& as, int left, int mid, int right) {
    int n1 = mid - left;
    int n2 = right - mid;
    vector<int> ls(n1 + 1), rs(n2 + 1);
    for (int i = 0; i < n1; i++) {
        ls[i] = as[left + i];
    }
    for (int i = 0; i < n2; i++) {
        rs[i] = as[mid + i];
    }
    ls[n1] = rs[n2] = INT_MAX;
    for (int i = 0, j = 0, k = left; k < right; k++) {
        if (ls[i] <= rs[j]) {
            as[k] = ls[i++];
        } else {
            as[k] = rs[j++];
        }
    }
    return right - left;
}

int merge_sort(vector<int>& as, int left, int right) {
    if (left + 1 >= right) {
        return 0;
    }
    int mid = (left + right) / 2;
    int ret = 0;
    ret += merge_sort(as, left, mid);
    ret += merge_sort(as, mid, right);
    ret += merge(as, left, mid, right);
    return ret;
}

