class Main {
public:
	int compare = 0;

	vector<int> merge(vector<int>& as, vector<int>& bs) {
		vector<int> ret;

		int ia=0;
		int ib=0;
		while (ia < as.size() && ib < bs.size()) {
			if (as[ia] <= bs[ib]) {
				ret.push_back(as[ia]);
				ia++;
				compare++;
			}
			else {
				ret.push_back(bs[ib]);
				ib++;
				compare++;
			}
		}

		while (ia < as.size()) {
			ret.push_back(as[ia]);
			ia++;
			compare++;
		}

		while (ib < bs.size()) {
			ret.push_back(bs[ib]);
			ib++;
			compare++;
		}

		return ret;
	}

	vector<int> mergeSort(vector<int>& as) {
		if (as.size() <= 1) {
			return as;
		}

		int mid = as.size() / 2;
		vector<int> former, latter;
		REP(i, as.size()) {
			if (i < mid) {
				former.push_back(as[i]);
			}
			else {
				latter.push_back(as[i]);
			}
		}

		former = mergeSort(former);
		latter = mergeSort(latter);
		vector<int> ret = merge(former, latter);

		return ret;
	}
};

