void merge(int A[], int l, int m, int r) {
	int n1 = m - l;
	int n2 = r - m;
	int *L = new int[n1];
	int *R= new int[n2];

	for (int i = 0; i < n1; ++i) {
		L[i] = A[l + i];
	}
	for (int i = 0; i < n2; ++i) {
		R[i] = A[m + i];
	}
	int i = 0;
	int j = 0;
	int k = l;
	for (; k < r; ++k) {
		if (i >= n1 || j >= n2) break;
		if (L[i] <= R[j]) {
			A[k] = L[i];
			i++;
		} else { 
			A[k] = R[j];
			j++;
		}
	}
	while (k < r) {
		if (i < n1) {
			A[k] = L[i];
			i++;
		} else {
			A[k] = R[j];
			j++;
		}
		k++;
	}
