void print(vector<int> array)
{
  for(int x:array){
    cout<<x<<" ";
  }
  cout<<endl;
}
void swap(int& a,int& b)
{
  if(a>=b){
    int tmp=a;
    a=b;
    b=tmp;
  }
}

vector<int> marge(vector<int>& list,int& count)
{
  int n=list.size();
  if(n==1){
    return list;
  }else if(n==2){
    swap(list[0],list[1]);
    count+=2;
    return list;
  }else{
    int half=n/2;
    vector<int> left(0);
    vector<int> right(0);

    for(int i=0;i<half;i++){
      left.push_back(list[i]);
    }

    for(int i=half;i<n;i++){
      right.push_back(list[i]);
    }

    left=marge(left,count);
    right=marge(right,count);
    vector<int> result(0);
    int i=0,j=0;
    while(result.size()<n){
      if(i==left.size()){
	while(j<right.size()){
	  result.push_back(right[j]);
	  j++;
	  count++;
	}
	break;
      }else if(j==right.size()){
	while(i<left.size()){
	  result.push_back(left[i]);
	  i++;
	  count++;
	}
	break;
      }
      if(left[i]<=right[j]){
	result.push_back(left[i]);
	i++;
	count++;
      }else{
	result.push_back(right[j]);
	j++;
	count++;
      }
    }
  }
  return result;
}

