void Merge(vector<int> &data, int left, int mid, int right)
{
    int n1 = mid - left;
    int n2 = right - mid;
    vector<int> L(n1 + 1), R(n2 + 1);

    for (int i = 0; i < n1; ++i)
        L[i] = data[left + i];
    for (int i = 0; i < n2; ++i)
        R[i] = data[mid + i];
    L[n1] = INF;
    R[n2] = INF;

