int partition(int *A, int l, int r) {
    int p = A[r];
    int i = l - 1;
    for (int j = l; j < r; j++) {
        if (A[j] <= p) {
            i++;
            std::swap(A[i], A[j]);
        }
    }
    std::swap(A[i+1], A[r]);
    return i + 1;
}
