int Merge(VI *vec, int left, int mid, int right) {
	VI &v = *vec;
	int n1 = mid - left;
	int n2 = right - mid;
	VI L(n1 + 1), R(n2 + 1);
	REP(i, n1) {
		L[i] = v[left + i];
	}
	REP(i, n2) {
		R[i] = v[mid + i];
	}
	L[n1] = R[n2] = numeric_limits<int>::max();
	int i = 0;
	int j = 0;
	int count = 0;
	FOR(k, left, right) {
		count++;
		if (L[i] <= R[j]) {
			v[k] = L[i];
			i++;
		} else {
			v[k] = R[j];
			j++;
		}
	}
	return count;
}

int MergeSort(VI *vec, int left, int right) {
	VI &v = *vec;
	int count = 0;
	if (left + 1 < right) {
		int mid = (left + right) / 2;
		count += MergeSort(&v, left, mid);
		count += MergeSort(&v, mid, right);
		count += Merge(&v, left, mid, right);
	}
	return count;
}

