int merge(int A[], int left, int mid, int right) {
    int c = 0;
    int n1 = mid - left + 2;
    int n2 = right - mid + 1;
    int L[n1], R[n2];
    for (int i=0; i<n1-1; i++) L[i] = A[left + i];
    for (int i=0; i<n2-1; i++) R[i] = A[mid + 1 + i];

    L[n1-1] = MN;
    R[n2-1] = MN;

    int l=0, r = 0;
    for (int i=left; i<=right; i++) {
        if (L[l] <= R[r]) {
            A[i] = L[l];
            l++;
        } else {
            A[i] = R[r];
            r++;
        }
        c++;
    }
    return c;
}

int merge_sort(int A[], int left, int right) {
    int c;
    if (left < right) {
        int mid = (left + right) / 2;
        merge_sort(A, left, mid);
        merge_sort(A, mid + 1, right);
        c = merge(A, left, mid, right);
    }
    return c;
}


