{
  int n1, n2,i,j,k;
  n1 = mid - left;
  n2 = right - mid;
  int L[n1],R[n2];

  for (i=0; i < n1; i++)
    L[i] = a[left + i];
  for (i=0; i < n2; i++)
    R[i] = a[mid+i];

  j=i=0;
