const int INF = 1e9+1;
template <typename T>
void merge(vector<T> &a, int left, int mid, int right, int &num){
  int n1 = mid - left;
  int n2 = right - mid;
  vector<T> L(n1+1), R(n2+1);
  for(int i=0; i<n1; i++) L[i] = a[left+i];
  for(int i=0; i<n2; i++) R[i] = a[mid+i];
  L[n1] = INF;
  R[n2] = INF;
  int l_id = 0, r_id = 0;
  for(int i=left; i<right; i++){
    if(L[l_id] <= R[r_id]){
      a[i] = L[l_id];
      l_id++;
    }
    else{
      a[i] = R[r_id];
      r_id++;
    }
    num++;
  }

  return;
}

