void Merge(int A[]; int left; int mid; int right){
	int n1 = mid - left;
	int n2 = right - mid;

	int* L = new int[n1+1];
	int* R = new int[n2+1];

	for(int i = 0; i<n1; i++){
		R[i] = A[mid+1];
