int merge(int A[], int left, int mid, int right){
	int c = 0, n1, n2;
	n1 = mid - left;
	n2 = right - mid;
	vector<int> L, R;
	REP(i, n1){
		L.push_back(A[left + i]);
	}
	REP(i, n2){
		R.push_back(A[mid + i]);
	}
	L.push_back(INFTY);
	R.push_back(INFTY);
	int i = 0, j = 0;
	FOR(k, left, right){
		if (L.at(i) <= R.at(j)){
			A[k] = L.at(i);
			i++;
		}
		else{
			A[k] = R.at(j);
			j++;
		}
		c++;
	}
	return c;
}
