int
merge(vector<int> &a, const int left, const int mid, const int right)
{
    int n1 = mid - left;
    vector<int> L(n1 + 1);
    for (int i = 0; i < n1; i++) {
        L[i] = a[left + i];
    }
    L[n1] = numeric_limits<int>::max();

    int n2 = right - mid;
    vector<int> R(n2 + 1);
    for (int i = 0; i < n2; i++) {
        R[i] = a[mid + i];
    }
    R[n2] = numeric_limits<int>::max();

    int i = 0;
    int j = 0;
    int count = 0;
    for (int k = left; k < right; k++) {
        if (L[i] <= R[j]) {
            a[k] = L[i++];
