using namespace std;

constexpr int INF = numeric_limits<int>::max();

int merge(vector<int>& s, int left, int mid, int right){
    int cnt = 0;
    int n1 = mid - left;
    int n2 = right - mid;
    vector<int> L(n1 + 1);
    vector<int> R(n2 + 1);
    for(int i = 0; i < n1; ++i){
        L[i] = s[left + i];
    }
    for(int i = 0; i < n2; ++i){
        R[i] = s[mid + i];
    }
    L[n1] = INF;
    R[n2] = INF;
    for(int k = left, i = 0, j = 0; k < right; ++k){
        ++cnt;
        if(L[i] <= R[j]){
            s[k] = L[i++];
        }else{
            s[k] = R[j++];
        }
    }
    return cnt;
}

int merge_sort(vector<int>& s, int left, int right){
    int cnt = 0;
    if(left + 1 < right){
        int mid = (left + right) / 2;
        cnt += merge_sort(s, left, mid);
        cnt += merge_sort(s, mid, right);
        cnt += merge(s, left, mid, right);
    }
    return cnt;
}

