deque<int> msort(deque<int> d) {
	if (d.size() == 1)return d;
	deque<int> l, r;
	int p = (d.size() + 1) / 2;
	rep(i, d.size()) {
		if (i < p)l.push_back(d[i]);
		else r.push_back(d[i]);
	}
	deque<int>ll = msort(l);
	deque<int>rr = msort(r);
	deque<int>dd =marge(ll, rr);
	return dd;
}


