void MergeSort(int *A, int left, int right)
{
  int mid,i,j,k;
   /* 配列の要素が一つの場合 */
  if (left>=right)             
    return;                     


  mid=(left+right)/2;      
  MergeSort(A,left,mid);       
  MergeSort(A,mid+1,right);  

  /* left から mid*/
  for(i=left;i<=mid;i++)
    temp[i]=A[i];

