    int mid = (start + end) / 2;
    count += merge_sort(N, start, mid, s);
    count += merge_sort(N, mid, end, s);

    int ti = 0;
    int left = start;
    int right = mid;
    while (left < mid && right < end) {
        if ((*s)[left] < (*s)[right]) {
            tmp[ti] = (*s)[left];
            left++;
            ti++;
        } else {
            tmp[ti] = (*s)[right];
            right++;
            ti++;
        }
        count++;
    }
    while (left < mid) {
        tmp[ti] = (*s)[left];
        left++;
        ti++;
        count++;
    }
    while (right < end) {
        tmp[ti] = (*s)[right];
        right++;
        ti++;
        count++;
    }

    for (int i = 0; i < end - start; i++) {
        (*s)[start + i] = tmp[i];
    }

    return count;
}

