  n2=right-mid;

  L=(int *)malloc(sizeof(int)*(n1+1));
  R=(int *)malloc(sizeof(int)*(n2+1));

  for(i=0;i<n1;i++) L[i]=data[left+i];
  for(i=0;i<n2;i++) R[i]=data[mid+i];

  L[n1]=R[n2]=INT_MAX;

  i=j=0;
  for(k=left;k<right;k++){
