int main(void)
{
    int data_num;			/* Data Num */
	int db;					/* Data Block */
	int cn = 2;				/* Compare Num */
	int mn = 0;				/* merge num */
	int half = 1;			/* Compare Half Num */
    int *pSortBuff;
	int remainder;          /* amari */
	int position;
	int loop;

    pSortBuff = (int *)malloc(sizeof(int) * MAX_DATA_NUM);
    /* get "Data Block Num" */
    scanf("%d", &db);

