        	{
        		Merge_Void(&(pSortBuff[position]), half, half);
        		position += cn;
        		mn += cn;
        	}

        	if(remainder > half)
        	{
        		Merge_Void(&(pSortBuff[position]), half, (remainder - half));
        		mn += remainder;
        	}

        	half = cn;
        	cn *= 2; /* double compare num */
        }

    }
    else
    {
        /* error input */
    }

	for(loop=0; loop<data_num-1; loop++)
	{
		printf("%d ", pSortBuff[loop]);
	}
