int count = 0;

void doMS(int A[], int head, int len)
{
    if (len < 2)
        return;
    int toplen = len / 2;
    int botlen = len - toplen;
    int tophead = head;
    int bothead = tophead + toplen;
    doMS(A, tophead, toplen);
    doMS(A, bothead, botlen);
    // merge top and bottom
    int res[len];
    int i = tophead;
    int j = bothead;
    int res_i = 0;
    while (i < tophead + toplen || j < bothead + botlen)
    {
        if (i >= tophead + toplen)
        {
            memcpy(res + res_i, A + j, sizeof(int) * (bothead + botlen - j));
            count += bothead + botlen - j;
            break;
        }
        if (j >= bothead + botlen)
        {
            memcpy(res + res_i, A + i, sizeof(int) * (tophead + toplen - i));
            count += tophead + toplen - i;
            break;
        }
        res[res_i++] = A[i] > A[j] ? A[j++] : A[i++];
        count++;
    }
    memcpy(A + head, res, sizeof(int) * len);
}

int doPartition(int *A, int n)
{
    int pilot = A[n - 1];
    int i = 0, j = 0, temp;
    for (j = 0; j < n - 1; j++)
    {
        if (A[j] < pilot)
        {
            temp = A[i];
            A[i] = A[j];
            A[j] = temp;
            i++;
        }
    }
    A[n - 1] = A[i];
    A[i] = pilot;
    return i;
}

void doQS(int *A, int n)
{
    if (n < 2)
        return;
    int anchor = doPartition(A, n);
    doQS(A, anchor);
    doQS(A + anchor + 1, n - anchor - 1);
}


