void merge(int* A, int left, int mid, int right) {
	int n1 = mid - left;
	int n2 = right - mid;
	int L[N], R[N];
	int i, j, k;

	for (i = 0; i <= n1 - 1; i++)
		L[i] = A[left + i];
	for (i = 0; i <= n2 - 1; i++)
		R[i] = A[mid + i];

	L[n1] = R[n2] = N;
	i = j = 0;

	for (k = left; k <= right - 1; k++) {
		if (L[i] <= R[j]) {
			A[k] = L[i];
			i++;
		} else {
			A[k] = R[j];
			j++;
		}
	}
	cnt += (i + j);
}

