int binarySearch(int n,int key,int A[n]){
  int left = 0;
  int right = n;
  int mid;
  while(left < right){
    mid = (left + right) / 2;
    if(A[mid] == key)
      return 1;
    else if(key < A[mid])
      right = mid;
    else
      left = mid + 1;
  }
  return 0;
}

