void quickSort(card *arr,int p,int r)
{
  int q;
  if(p<r)
    {
      q=partition(arr,p,r);
      quickSort(arr,p,q-1);
      quickSort(arr,q+1,r);
    }
}
int partition(card *arr,int p,int r)
{
  int i;//counter
  int parlast;//last index of first half part
  int sep=arr[r].x;//separate number
  parlast=p-1;
  for(i=p;i<r;i++)
    {
      if(arr[i].x<=sep)
	{
	  parlast++;
	  swap(arr,parlast,i);
	}
    }
  swap(arr,parlast+1,r);
  return parlast+1;
}
void swap(card *arr,int x,int y)
{
  card temp;
  temp=arr[x];
  arr[x]=arr[y];
  arr[y]=temp;
}
