void MergeSort(int left,int right,int a[]){
  int m,i,j,k;

  //printf("%d,%d,%d\n",left,right,a[0]);
  if(left>=right){
    return;
  }
  //ここまではok

  m=(left+right)/2;
  //左側を再起で呼び出し
  MergeSort(left,m,a);
  //右側を呼び出し
  MergeSort(m+1,right,a);

  //a[left]からa[m]を作業領域にコピー
  for(i=left;i<=m;i++){
    temp[i]=a[i];
    //printf("%d,",temp[i]);
  }

  //a[m+1]からa[right]を逆順にコピー　
  for(i=m+1,j=right;i<=right;i++,j--){
    temp[i]=a[j];
  }

  i=left;
  j=right;
  //小さい方から配列に戻す
  for(k=left;k<=right;k++){
    cnt++;
    if(temp[i]<temp[j]){
      a[k]=temp[i++];
    }else{
      a[k]=temp[j--];
    }
  }

}
