#define SENTINEL 2000000000

static int merge(int *a, int left, int mid, int right) {
  int n1, n2, i, j, k, cnt;
  int *l;
  int *r;

  n1 = mid - left;
  l = (int *) malloc(sizeof(int) * (n1 + 1));
  if (l == NULL) return 0;
  for (i = 0; i < n1; ++i) l[i] = a[left + i];
  l[i] = SENTINEL;

  n2 = right - mid;
  r = (int *) malloc(sizeof(int) * (n2 + 1));
  if (r == NULL) return 0;
  for (i = 0; i < n2; ++i) r[i] = a[mid + i];
  r[i] = SENTINEL;

  for (i = j = cnt = 0, k = left; k < right; ++k) {
    ++cnt;
    if (l[i] <= r[j]) {
      a[k] = l[i++];
    } else {
      a[k] = r[j++];
    }
  }

  free(l);
  free(r);
  return cnt;
}

static int merge_sort(int *a, int left, int right) {
  int mid, cnt;

  cnt = 0;
  if (left >= right - 1) return cnt;

  mid = (left + right) / 2;
  cnt += merge_sort(a, left, mid);
  cnt += merge_sort(a, mid, right);
  cnt += merge(a, left, mid, right);
  return cnt;
}

