int merge(int *A,int l,int r,int m){

  int cnt=0,i,j,k,n1,n2;
  n1=m-l;
  n2=r-m;
  int L[n1+1],R[n2+1];
  for(i=0;i<n1;i++) L[i]=A[l+i];
  for(i=0;i<n2;i++) R[i]=A[m+i];
  L[n1]=(int)INFINITY;
  R[n2]=(int)INFINITY;
  i=0;
  j=0;
  for(k=l;k<r;k++){
    if(L[i]<=R[j])  A[k]=L[i++];
    else            A[k]=R[j++];
    cnt++;
  }
  return cnt;
}

