void merge(int s[], int left, int mid, int right){
    int i;
    int n1 = mid - left + 1;
    int n2 = right - mid + 1;
    int L[n1], R[n2];
    for(i = 0; i < (n1 - 1); i++){
        L[i] = s[left + i];
    }

    for(i = 0; i < (n2 - 1); i++){
        R[i] = s[mid + i];
    }

    L[n1 - 1] = SENTINEL;
    R[n2 - 1] = SENTINEL;

    int i = 0;
    int j = 0;

    for(k = left; k < right; k++){
        if(L[i] <= R[j]){
            s[k] = L[i];
            i++;
        }
        else {
            s[k] = R[j];
            j++;
        }
            count++;
    }
}

