void merge(int A[],int left,int mid,int right)
{
  int n1,n2,L[mid - left + 1],R[right - mid + 1],i,j,k,lc=0,rc=0;

  n1 = mid - left;
  n2 = right - mid;

  for(i = 0 ; i < n1 ; i++)
    {
      L[i] = A[left + i];
      lc++;  /* leftの要素のカウント */
    }

  for(i = 0 ; i < n2 ; i++)
    {
      R[i] = A[mid + i];
      rc++;  /* rightの要素のカウント */
    }

  L[n1] = INFINITY;
  R[n2] = INFINITY;

  i = 0;
  j = 0;

  for(k = left ; k < right ; k++)
    {

      count++;

      if(L[i] <= R[j])
	{
	  lc--;
	  A[k] = L[i];
	  L[i] = numMAX;  /* 比べ終わったら最大値を代入 */
	  if(lc > 0) i++;  /* leftがまだあるなら */
	}

      else
	{
	  rc--;
	  A[k] = R[j];
	  R[j] = numMAX;  /* 比べ終わったら最大値を代入 */
	  if(rc > 0) j++;  /* rightがまだあるなら */
	}
    }

  return;
}

void mergeSort(int A[],int left,int right)
{
  int mid;

  if(left + 1 < right)
    {
      mid = (left + right) / 2;
      mergeSort(A,left,mid);
      mergeSort(A,mid,right);
      merge(A,left,mid,right);
    }
  return;
}

#include <stdio.h>

#define MAX_DATA 10

int temp[MAX_DATA];    /* 最小でも配列と同じサイズの領域が必要 */

void MergeSort(int x[ ], int left, int right);
void main(void);

  /* 配列 x[ ] の left から right の要素のマージソートを行う */
void MergeSort(int x[ ], int left, int right)
{
    int mid, i, j, k;

    if (left >= right)              /* 配列の要素がひとつなら */
        return;                     /* 何もしないで戻る */

                                    /* ここでは分割しているだけ */
    mid = (left + right) / 2;       /* 中央の値より */
    MergeSort(x, left, mid);        /* 左を再帰呼び出し */
    MergeSort(x, mid + 1, right);   /* 右を再帰呼び出し */

      /* x[left] から x[mid] を作業領域にコピー */
    for (i = left; i <= mid; i++)
        temp[i] = x[i];

      /* x[mid + 1] から x[right] は逆順にコピー */
    for (i = mid + 1, j = right; i <= right; i++, j--)
        temp[i] = x[j];

    i = left;         /* i とj は作業領域のデーターを */
    j = right;        /* k は配列の要素を指している */

    for (k = left; k <= right; k++)    /* 小さい方から配列に戻す */
        if (temp[i] <= temp[j])        /* ここでソートされる */
            x[k] = temp[i++];
        else
            x[k] = temp[j--];
}

void main(void)
{
    int i;
      /* ソートされるデータ */
    int x[ ] = {9, 4, 6, 2, 1, 8, 0, 3, 7, 5};

      /* ソート前のデータを表示 */
    printf("ソート前\n");
    for (i = 0; i < MAX_DATA; i++)
        printf("%d\t", x[i]);

    MergeSort(x, 0, MAX_DATA - 1);

      /* ソート後のデータを表示 */
    printf("ソート後\n");
    for (i = 0; i < MAX_DATA; i++)
        printf("%d\t", x[i]);
}

