void Merge(int *a,int l,int m,int r){
  int n1,n2,i,j,k;
  int *L,*R;
  n1=m - l;
  n2=r - m;
  L=(int *)malloc((n1+1) * sizeof(int));
  R=(int *)malloc((n2+1) * sizeof(int));
  for(i=0;i<n1;i++){
    L[i]=a[l+i];
  }

  for(i=0;i<n2;i++){
    R[i]=a[m+i];

  }

  L[n1]=INFINITY;
  R[n2]=INFINITY;
  i=0;
  j=0;
  for(k=l;k<r;k++){
    if(L[i]<R[j]){
      a[k] = L[i];
      i=i+1;
    }
    else{
      a[k] = R[j];
      j=j+1;
    }
    count++; }
  free(R);
  free(L);

}


void MergeSort(int*a,int l,int r){
  int m;
  if(l+1<r){
    m = (l+r)/2;

    MergeSort(a,l,m);
    MergeSort(a,m,r);
    Merge(a,l,m,r);
  }
}

