	for(k=left,i=0,j=0;k<right;k++) {
		if(L[i] == SENTINEL && R[j] == SENTINEL) {
			break;
		} else if(L[i] == SENTINEL && R[j] != SENTINEL) {
			A[k] = R[j];
			j++;
			count++;
		} else if(R[j] == SENTINEL && L[i] != SENTINEL) {
			A[k] = L[i];
			i++;
			count++;
		} else if(L[i] <= R[j]) {
			A[k] = L[i];
			i++;
			count++;
		} else if(R[j] != -1){
			A[k] = R[j];
			j++;
			count++;
		}
	}
	return count;
}

