int[] merge(int[] a, int[] b)
{
    int[] res;
    res.reserve(a.length+b.length);
    while(a.length != 0 && b.length != 0)
    {
        if(a.front < b.front)
        {
            res ~= a.front;
            a.popFront();
        }else{
            res ~= b.front;
            b.popFront();
        }
    }
    res ~= a ~ b;
    count+=res.length;
    return res;
}

