void Merge(int A[],int left,int mid,int right){

  int n1 = mid - 1;
  int n2 = right - left + 1;
  int count = left;
  int store[n2+8];
  int i;

  while((left <= n1) && (mid <= right)){

    if(A[left] <= A[mid])
      store[count++] = A[left++];

    else
      store[count++] = A[mid++];
  }

  while (left <= n1)
    store[count++] = A[left++];

  while (mid <= right)
    store[count++] = A[mid++];

  for(i=0;i<= n2;i++){
    A[right] = store[right];
    right--;
  }

}

