void merge(int A[], int left, int mid, int right){
  int n1, n2, i, j, k;
  int *L, *R;

  n1 = mid - left;
  n2 = right - mid;
  L = malloc( (n1+1)*sizeof(int) );
  R = malloc( (n2+1)*sizeof(int) );
  for(i=0; i<=n1-1; i++) L[i] = A[left + i];
  for(j=0; j<=n2-1; j++) R[j] = A[mid + j];

  L[n1] = INFINITY;
  R[n2] = INFINITY;
  i = 0;
  j = 0;
  for(k=left; k<right; k++){
    if(L[i] <= R[j]){
      A[k] = L[i];
      i++;
      count++;
    }
    else{
      A[k] = R[j];
      j++;
      count++;
    }
  }
  free(L);
  free(R);
}

