        temp[i] = x[i];

    for (i = mid + 1, j = right; i <= right; i++, j--)
        temp[i] = x[j];

    i = left;         
    j = right;        

    for (k = left; k <= right; k++)    
        if (temp[i] <= temp[j])        
            x[k] = temp[i++];
        else
            x[k] = temp[j--];
}

