  int i, j, k;

  for( i = left; i <= mid; ++i){
    work[i] = array[i];
  }

  for( i = mid + 1, j = right; i <= right; ++i, --j){
    work[i] = array[j];
  }

  i = left;
  j = right;

  for( k = left; k <= right; ++k) {
    if( work[i] <= work[j] ){
      array[k] = work[i];
      ++i;
    }
    else{
      array[k] = work[j];
      --j;
    }
    count++;
