void merge(int numbers[], int temp[], int left, int mid, int right)
{
  int i, end_left, num_elements, tmp_pos;

  end_left = mid - 1;
  tmp_pos = left;
  num_elements = right - left + 1;

  while ((left <= end_left) && (mid <= right))
  {
    if (numbers[left] <= numbers[mid])
    {
      temp[tmp_pos] = numbers[left];
      tmp_pos = tmp_pos + 1;
      left = left +1;
    	cnt++;
