void arr_printer(const int *arr, const int N) {
    char buf[11];
    int n;
    for(int i = 0; i < N-1; ++i) {
        n = arr[i];
        if(!n) {
            putchar_unlocked('0');
            putchar_unlocked(' ');
            continue;
        }
        int j = 0;
        while(n) buf[j++] = (char)(n % 10 + '0'), n /= 10;
        while(j--) putchar_unlocked(buf[j]);
        putchar_unlocked(' ');
    }
    n = arr[N-1];
    if(!n){
        putchar_unlocked('0');
        putchar_unlocked('\n');
        return;
    }
    int j=0;
    while(n) buf[j++] = (char)(n % 10 + '0'), n /= 10;
    while(j--) putchar_unlocked(buf[j]);
    putchar_unlocked('\n');
}

int get_uint() {
    int n = 0;
    int c = getchar_unlocked();
    if(c < 48 || 57 < c) return c;
    while(47 < c && c < 58) {
        n = 10 * n + (c & 0xf);
        c = getchar_unlocked();
    }
    return n;
}
