void merge(int low, int high) 
{ 
   int i, j, k, p, mid; 

   if (low < high) {
	   mid = (low + high) >> 1;
	   merge(low, mid);
	   merge(mid+1, high);

	   p = 0; cnt += high-low+1;
	   k = i = low; while (i <= mid) w[p++] = a[i++];
	   j = 0; while (i <= high && j < p) {
		   if (w[j] <= a[i]) a[k++] = w[j++];
		   else              a[k++] = a[i++];
	   }
	   while (j < p) a[k++] = w[j++];
   }
}

