    tmp[0] = A[l];
    return tmp;
  }
  int *L, *R;
  L = (int *)malloc(sizeof(int) * ((r - l) / 2));
  R = (int *)malloc(sizeof(int) * ((r - l + 1) / 2));
  L = marge(A, l, (l + r) / 2);
