#define SENTINEL 1000000001

int g_num_swap = 0;

void merge(int *a, int left, int mid, int right) {
	int n1, n2, *L, *R, i, j, k;

	n1 = mid - left;
	n2 = right - mid;
	L = malloc(sizeof(int)*n1 + 1);
	R = malloc(sizeof(int)*n2 + 1);
	for (i = 0; i < n1; i++) {
		L[i] = a[left + i];
	}
	for (i = 0; i < n2; i++) {
		R[i] = a[mid + i];
	}
	L[n1] = R[n2] = SENTINEL;

	i = j = 0;
	for (k = left; k < right; k++) {
		if (L[i] <= R[j]) {
			a[k] = L[i++];
		} else {
			a[k] = R[j++];
		}
		g_num_swap++;
	}
	free(L);
	free(R);
}

