int getNum(void) {
	int n = 0;
	while ((*p >= '0') && (*p <= '9')) {
		n = n * 10 + (int)(*p - '0');
		++p;
	} 
	++p;
	return n;
}

void putNum(int n) {
	int d = n / 10;
	if (n < 10) {
		*p = '0' + (char)n;
		++p;
		return;
	}
	if (d) putNum(d);
	*p = '0' + (char)(n % 10);
	++p;
}

