void MergeSort(int x[ ], int left, int right)
{
    int mid, i, j, k;

    if (left >= right)              
        return;                     


    mid = (left + right) / 2;      
    MergeSort(x, left, mid);        
    MergeSort(x, mid + 1, right);   


    for (i = left; i <= mid; i++)
        temp[i] = x[i];


    for (i = mid + 1, j = right; i <= right; i++, j--)
        temp[i] = x[j];

    i = left;         
    j = right;        

    for (k = left; k <= right; k++)    
      if (temp[i] <= temp[j]){      
	x[k] = temp[i++];
	count++;}
      else{
	x[k] = temp[j--];
	count++;}

}

