	int db;					/* Data Block */
	int cn = 2;				/* Compare Num */
	int mn = 0;				/* merge num */
	int half = 1;			/* Compare Half Num */
//	int pSortBuff[10] = {0, 3, 3, 2, 9, 0, 8, 2, 6, 6};
//	int *pSortBuff;
	int pSortBuff[MAX_DATA];
