void swapInt( int *n1, int *n2) {

int tmp;

tmp = *n1;
*n1 = *n2;
*n2 = tmp;

}

void swapChar( char *c1, char *c2) {

char tmp;

tmp = *c1;
*c1 = *c2;
*c2 = tmp;

}


int partition( int *a, char *c, int p, int r) {

int x;
int i, j;

x = a[r];
i = p-1;

for( j=p; j<r; j++) {
  if( a[j] <= x ) {
    i++;
    swapInt( &a[i], &a[j]);
    swapChar( &c[i], &c[j]);
  }
}
swapInt( &a[i+1], &a[r]);
swapChar( &c[i+1], &c[r]);
return i+1;

}


quickSort(int*  a, char* c, int p, int r) {

  int q;

  if( p < r) {
    q = partition( a, c, p, r);
    quickSort( a, c, p, q-1);
    quickSort( a, c, q+1, r);
  }
} 


