void Merge(int A[], int p,int q,int r,int B[],int *count)
{
  int t;
  int i,left, right,k;
  k = p; left = p; right = q+1;
  while(k <= r)
  {
    if(right>r) t = A[left++];
    else if(left>q) t = A[right++];
    else if(A[left]<=A[right]) t = A[left++];
    else t =A[right++];
    B[k++]=t;
    Count(count);
  }
  for (i=p;i<=r;i++) A[i]=B[i];
}

