int partion(int A[], int l, int r)
{
	int i, j, pivot, t;

	i = l - 1;
	j = r;
	pivot = A[r];

	for (;;)
	{
		while (A[++i] < pivot)
			;
		while (i < --j && pivot < A[j])
			;

		if (i >= j)
			break;
		swap(&A[i], &A[j]);
	}

	swap(&A[i], &A[r]);
	return i;
}

void quickSort2(int A[], int l, int r)
{
	int v;

	if (l >= r)
		return;

	v = partion(A, l, r);

	quickSort2(A, l, v-1);

	quickSort2(A, v+1, r);
}

void quickSort(int A[], int n)
{
	quickSort2(A, 0, n - 1);
}

