int partition(int *A,int p,int r){
  int x,i,j,s;
  x=A[r];
  i=p-1;
  for(j=p;j<r;j++){
    if(A[j]<=x){
      i=i+1;
      s=A[j];
      A[j]=A[i];
      A[i]=s;
    }
  }
  s=A[r];
  A[r]=A[i+1];
  A[i+1]=s;
  return i+1;
}

