class Main {

    companion object {

        private lateinit var inputs: List<Int>

        private var compareCount = 0

        fun init() {

            readLine()

            inputs = readLine()!!.split(" ").map { it.toInt() }

        }

        fun execute() {
            println(mergeSort(inputs).joinToString(" "))
            println(compareCount)
        }


        /**
         * 配列をまーじそーと。
         */
        fun mergeSort(list: List<Int>): List<Int> {

            if (list.size == 1) {
                return list
            }

            val mediumIndex = (list.size / 2.0).toInt()

            val sortList1 = if (mediumIndex == 1)
                arrayListOf(list[0])
            else mergeSort(list.subList(0, mediumIndex))

            val sortList2 = if (mediumIndex - list.size == 1)
                arrayListOf(list[mediumIndex])
            else mergeSort(list.subList(mediumIndex, list.size))

            val orderList = arrayListOf<Int>()

            var sortList1Index = 0
            var sortList2Index = 0
            while (orderList.size != (sortList1.size + sortList2.size)) {

                compareCount++

                /**
                 * 空の確認
                 */
                if (sortList2.size == sortList2Index) {
                    orderList.add(sortList1[sortList1Index])
                    sortList1Index++
                    continue
                } else if (sortList1.size == sortList1Index) {
                    orderList.add(sortList2[sortList2Index])
                    sortList2Index++
                    continue
                }

                /**
                 * 比較
                 */
                if (sortList1[sortList1Index] < sortList2[sortList2Index]) {
                    orderList.add(sortList1[sortList1Index])
                    sortList1Index++
                } else {
                    orderList.add(sortList2[sortList2Index])
                    sortList2Index++
                }
            }

            return orderList
        }
    }
}

fun main(args: Array<String>) {
    readLine()!!.toInt()
    val list = readLine()!!.split(' ').map { it.toInt() }

    val (sortedList, cnt) = mergeSort(list)

    println(sortedList.joinToString(" "))
    println(cnt)
}

private fun mergeSort(list: List<Int>): Pair<List<Int>, Int> {

    val array = list.toIntArray()
    var cnt = 0

    fun merge(left: Int, mid: Int, right: Int) {

        val leftArray = IntArray(mid - left + 1) { Int.MAX_VALUE }
        for (i in (0 until mid - left)) {
            leftArray[i] = array[left + i]
        }

        val rightArray = IntArray(right - mid + 1) { Int.MAX_VALUE }
        for (i in (0 until right - mid)) {
            rightArray[i] = array[mid + i]
        }

        var i = 0
        var j = 0

        for (k in left until right) {
            cnt++
            if (leftArray[i] <= rightArray[j]) {
                array[k] = leftArray[i++]
            } else {
                array[k] = rightArray[j++]
            }
        }
    }

    fun sort(left: Int, right: Int) {
        if (left + 1 < right) {
            val mid = (left + right) / 2
            sort(left, mid)
            sort(mid, right)
            merge(left, mid, right)
        }
    }

    sort(0, list.size)

    return array.toList() to cnt
}

