			countMergeSortLeft = mergeSort(afterA, left, mid);
			countMergeSortRight = mergeSort(afterA, mid, right);
			countSum = merge(afterA, left, mid, right);
		}
		return countSum + countMergeSortLeft + countMergeSortRight;
	}

