		Scanner sc = new Scanner(System.in);
		Printer pr = new Printer(System.out);

		int n = sc.nextInt();
		int[] s = new int[n];
    	for (int i = 0; i < n; i++) {
    		s[i] = sc.nextInt();
    	}

    	count = 0;
    	mergeSort(s, 0, n);

    	pr.printArray(s);
    	pr.println(count);

    	pr.close();
