	public static void mergeSort(int[] a, int left, int right) {
		if (left + 1 < right) {
			int mid = (left + right) / 2;
			mergeSort(a, left, mid);
			mergeSort(a, mid, right);
			merge(a, left, mid, right);
		}
	}

	public static void merge(int[] a, int left, int mid, int right) {
		int n1 = mid - left;
		int n2 = right - mid;
		int[] l = new int[n1];
		int[] r = new int[n2];
		for (int i = 0; i < n1; i++) {
			l[i] = a[left + i];
		}
		for (int i = 0; i < n2; i++) {
			r[i] = a[mid + i];
		}
		for (int i = 0, j = 0, k = left; k < right; k++) {
			count++;
			if (i < n1 && j < n2) {
				if (l[i] <= r[j]) {
					a[k] = l[i];
					i++;
				} else {
					a[k] = r[j];
					j++;
				}
			} else {
				if (j >= n2) {
					a[k] = l[i];
					i++;
				} else if (i >= n1) {
					a[k] = r[j];
					j++;
				} else {
					// Error
					count = -99999;
				}
			}
		}
	}

