			strbuf.append(n);
			checkStringBuffer();
		}

		void printArray(int[] array) {
			for (int i = 0; i < array.length; i++) {
				checkStringBuffer();
				strbuf.append(array[i]);
				strbuf.append(" ");
			}
			strbuf.delete(strbuf.length() - 1, strbuf.length());
			strbuf.append(CR);
		}

		void close() {
			flashStringBuffer();

			try {
				bw.close();
			} catch (IOException e) {
				e.printStackTrace();
			}
		}

		private void flashStringBuffer() {
			if (strbuf.length() > 0) {
				try {
					bw.write(strbuf.toString());
				} catch (IOException e) {
					e.printStackTrace();
				}
				strbuf.setLength(0);
			}
		}

		private void checkStringBuffer() {
			if (strbuf.length() > bufSize) {
				flashStringBuffer();
			}
		}
	}
}

