    void merge(int[] A, int left, int mid, int right) {
        final int INF = Integer.MAX_VALUE;
        int n1 = mid - left, n2 = right - mid;
        int[] L = new int[n1 + 1], R = new int[n2 + 1];
        for (int i = 0; i < n1; i++) {
