		if(l+1>=r) return 0;
		if(l+2==r) {
			if(A[l]<=A[l+1]) return 0;
			int swap=A[l+1];
			A[l+1]=A[l];
			A[l]=swap;
			return 1;
		}
		int m=(l+r)/2;
		int cl=merge(l, m);
		int cr=merge(m, r);
		int c=0;
		int i=l, j=m, k=l;
		while(i<m && j<r) {
			if(A[i]<=A[j]) {
				W[k++]=A[i++];
				c++;
			}
