	public static void mergeSort(int[] s,int left, int right){

		if(right - left == 1){
			return;
		}
		int mid = (right + left) / 2;
		mergeSort(s,left,mid);
		mergeSort(s,mid,right);
 		merge(s,left,mid,right);
	}


	private static void merge(int[] s,int left, int mid, int right){

