		for(int i = mid ; i < right ; i++) R[ri++] = s[i];
		R[ri] = SENTINAL;

		li = ri = 0;

		for(int i = left ; i < right ; i++){
			count++;
			if(L[li] < R[ri]){
				s[i] = L[li++];
			}else{
				s[i] = R[ri++];
			}
		}
