	private static void mergeSort(int[] arr) {		
		mergeSort(0, arr.length - 1, arr);
	}

	private static void mergeSort(int floor, int ceiling, int[] arr) {		
		if (floor < ceiling) {
			int mid = floor + (ceiling - floor) / 2;
			mergeSort(floor, mid, arr);
			mergeSort(mid + 1, ceiling, arr);
			merge(floor, mid, ceiling, arr);
		}		
	}

	private static void merge(int floor, int mid, int ceiling, int[] arr) {

		int[] tempArray = new int[arr.length];
		for (int i = floor; i <= ceiling; i++) {
			tempArray[i] = arr[i];
		}

		int i = floor;
		int j = mid + 1;
		int k = floor;
		while (k <= ceiling) {
			count++;
			if (j > ceiling || (i <= mid && tempArray[i] < tempArray[j])) {
				arr[k] = tempArray[i];
				i++;
			} else {
				arr[k] = tempArray[j];
				j++;
			}
			k++;
		}
	}
