	public void merging(int[] list, int nl, int nm, int nr) {
		int n1 = nm - nl;
		int n2 = nr - nm;
		int[] l = new int[n1 + 1];
		int[] r = new int[n2 + 1];
		for (int i = 0; i < n1; i++) {
			l[i] = list[nl + i];
		}
		for (int i = 0; i < n2; i++) {
			r[i] = list[nm + i];
		}
