  private static int mergesort(int[] a, int l, int r){
    int m, c;
    if(l + 1 >= r)return 0;
    else{
      m = (l + r) / 2;
      c = mergesort(a, l, m);
      c += mergesort(a, m, r);
      c += merge(a, l, m, r);
      return c;
    }
  }

  private static int merge(int[] a, int l, int m, int r){
    int nl, nr, count;
    int i, j, k;
