        count += mergeSort(s, n, mid, right);
        count += merge(s, n, left, mid, right);
        return count;
    }

    private static int merge(int[] s, int n, int left, int mid, int right) {
        int n1 = mid - left;
        int n2 = right - mid;
        int[] l = new int[n1 + 1];
