				if(l_pos == left + l_size){
					tmp[left + count] = A[r_pos];
					r_pos++;
					count++;
					ret++;
				}else if(r_pos == mid + r_size){
					tmp[left + count] = A[l_pos];
					l_pos++;
					count++;
					ret++;
				}else if(A[l_pos] <= A[r_pos]){
					tmp[left + count] = A[l_pos];
					l_pos++;
					count++;
					ret++;
				}else{
					tmp[left + count] = A[r_pos];
					r_pos++;
					count++;
					ret++;
				}
