	static List<Integer> merge(List<Integer> A, List<Integer> B) {

		List<Integer> C=new ArrayList<>();

		while(!A.isEmpty() && !B.isEmpty()) {
			cc++;
			int a=A.get(0),b=B.get(0);

			if(a<b) {
				C.add(a);
				A.remove(0);
			}
			else if(a>b) {
				C.add(b);
				B.remove(0);
			}
			else {
				C.add(a);C.add(b);
				A.remove(0);B.remove(0);
				cc++;
			}
		}

		if(A.isEmpty()) {
			while(!B.isEmpty()) {
				C.add(B.get(0));
				B.remove(0);
				cc++;
			}
		}
		else {
			while(!A.isEmpty()) {
				C.add(A.get(0));
				A.remove(0);
				cc++;
			}
		}

		return C;
	}

