        System.arraycopy(a, m, R, 0, n2);
        L[n1] = R[n2] = Integer.MAX_VALUE;
        int i = 0, j = 0;
        for(int k = l; k<r; k++){
            if(L[i]<=R[j]) a[k] = L[i++];
            else a[k] = R[j++];
            t++;
        }
    }
