class Solve {
	private int n;
	private int[] S;

	public Solve(final int n, final int[] S)
	{
		this.n = n;
		this.S = S;
	}

	public void solve()
	{
		int[] A = S;
		final int count = mergeSort(A, 0, n);

		System.out.println(String.join(" ",
							Arrays.stream(A)
								.boxed().map(n -> n.toString()).toArray(String[]::new)));
		System.out.println(count);

	}

	public int mergeSort(int[] A, final int left, final int right)
	{
		final int mid = (left + right) / 2;
		int count = 0;

		if(left + 1 < right)
		{
			count += mergeSort(A, left, mid);
			count += mergeSort(A, mid, right);
			count += merge(A, left, mid, right);
		}
		return count;
	}

	public int merge(int[] A, final int left, final int mid, final int right)
	{
		final int n1 = mid - left;
		final int n2 = right - mid;
		int[] L = new int[n1 + 1];
		int[] R = new int[n2 + 1];

		for(int i=0, l=n1; i < l; i++)
		{
			L[i] = A[i + left];
		}

		for(int i=0, l=n2; i < l; i++)
		{
			R[i] = A[i + mid];
		}

		L[n1] = Integer.MAX_VALUE;
		R[n2] = Integer.MAX_VALUE;

		int count = 0;
		int i = 0;
		int j = 0;

		for(int k=left; k < right; k++)
		{
			++count;

			if(L[i] <= R[j]) A[k] = L[i++];
			else A[k] = R[j++];
		}

		return count;
	}
}
