        // Here your code !
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine());
        int[] S = Stream.of(br.readLine().split(" ")).mapToInt(Integer::parseInt).toArray();
        int[] R = mergeSort(S, 0, n-1);

