    for(int i = 0; i<n1;i++){
      L[i] = A[left+i];
    }
    for(int i =0; i<n2; i++){
      R[i] = A[i+mid];
    }
    L[n1] = (int)Double.POSITIVE_INFINITY;
    R[n2] = (int)Double.POSITIVE_INFINITY;
    int i = 0;
    int j = 0;
    for(int k = left; k<right; k++){
      count++;
      if(L[i]<=R[j]){
        A[k] = L[i++];
      }else{
        A[k] = R[j++];
      }
    }
  }

  static void merge_sort(int A[], int n, int left, int right){
    if(left+1<right){
      int mid = (left+right)/2;
