class Main {
    public static int count = 0;
    public static void main(String[] args) {
	Scanner in = new Scanner(System.in);
	int n = in.nextInt();
	int[] S = new int[n];
	for (int i = 0; i < n; i++) {
	    S[i] = in.nextInt();
	}
