namespace ALDS1_5_B
{
    public static class Algorithm
    {
        public static int Count;

        public static void MergeSort<T>(this T[] a) where T : IComparable<T>
        {
            Count = 0;
            MergeSort(a, 0, a.Length);
        }

        private static void Merge<T>(this T[] a, int l, int m, int r) where T : IComparable<T>
        {
            int n1 = m - l, n2 = r - m;
            T[] a1 = new T[n1], a2 = new T[n2];
            for (int i = 0; i < n1; i++) a1[i] = a[l + i];
            for (int i = 0; i < n2; i++) a2[i] = a[m + i];
            int i1 = 0, i2 = 0, k = l;
            while (i1 < n1 && i2 < n2)
            {
                if (a1[i1].CompareTo(a2[i2]) <= 0) a[k++] = a1[i1++];
                else a[k++] = a2[i2++];
                Count++;
            }
            Count += n1 - i1 + n2 - i2;
            while (i1 < n1) a[k++] = a1[i1++];
            while (i2 < n2) a[k++] = a2[i2++];
        }
        private static void MergeSort<T>(this T[] a, int s, int t) where T : IComparable<T>
        {
            if (s + 1 < t)
            {
                var mid = (s + t) >> 1;
                MergeSort(a, s, mid);
                MergeSort(a, mid, t);
                Merge(a, s, mid, t);
            }
        }
    }

