                {
                    Console.Write(A[i] + "\r\n");
                    break;
                }
                Console.Write(A[i] + " ");
            }
            Console.WriteLine(count);
        }

        static int[] MergeSort(int[] Array, int n, int left, int right)
        {
            if (left + 1 < right)
            {
                int mid = (left + right) / 2;
                Array = MergeSort(Array, n, left, mid);
                Array = MergeSort(Array, n, mid, right); //もっとも小さい配列に分解していく(要素数1まで)
                Array = Merge(Array, n, left, mid, right); //大小を比べて併合していく
