namespace B
{
    class Merge
    {
        public int count = 0;

        public void merge(ref int[] A, int left, int mid, int right)
        {
            int i, j=0, k;
            int n1 = mid - left;
            int n2 = right - mid;
            int[] L = new int[n1 + 1];
            int[] R = new int[n2 + 1];
            for (i = 0; i < n1; i++)
            {
                L[i] = A[left + i];
            }
            for (i = 0; i < n2; i++)
            {
                R[i] = A[mid + i];
            }
            L[n1] = int.MaxValue;
            R[n2] = int.MaxValue;
            i = 0;
            for (k = left; k < right; k++)
            {
                if (L[i] <= R[j])
                {
                    A[k] = L[i];
                    i++;
                    count++;
                }
                else
                {
                    A[k] = R[j];
                    j++;
                    count++;
                }
            }

        }

        public void mergeSort(ref int[] A, int left, int right)
        {
            if (left+1<right)
            {
                int mid = (left + right) / 2;
                mergeSort(ref A, left, mid);
                mergeSort(ref A, mid, right);
                merge(ref A, left, mid, right);
            }
        }
    }

