        {
            int lenght = data_ary.Length;
            int left_n = mid_ind - left_ind;  //left_indからmid_ind - 1の要素数
            int right_n = right_ind - mid_ind;  //mid_indからright_ind - 1までの要素数

            //番兵を入れるため1つ余分に確保
            int[] left_ary = new int[left_n + 1];
            int[] right_ary = new int[right_n + 1];

            //left_indからleft_ind + left_n - 1まで
            for (int i = 0; i < left_n; i++)
            {
                left_ary[i] = data_ary[left_ind + i];
            }

            //mid_indからmid_ind + right_n - 1まで
            for(int i = 0; i < right_n; i++)
            {
                right_ary[i] = data_ary[mid_ind + i];
            }

            //最後の要素に番兵を入れる
            left_ary[left_n] = SENTINEL;
            right_ary[right_n] = SENTINEL;

            int l = 0;
            int r = 0;

            //比べる回数はright_n - left_n
            //よって、番兵同士が比べれられることはない
