        public static int merge (int[] list, int left, int middle, int right)
        {
            int count = 0;
            int n1 = middle - left;
            int n2 = right - middle;
            int[] L = new int[n1 + 1];
            int[] R = new int[n2 + 1];
            for (int i = 0; i < n1; i++)
            {
                L[i] = list[left + i];
            }
            for (int i = 0; i < n2; i++)
            {
                R[i] = list[middle + i];
            }

            L[n1] = int.MaxValue;
            R[n2] = int.MaxValue;

            int p = 0;
            int q = 0;
            for (int i = left; i < right; i++)
            {
                if (L[p] <= R[q])
                {
                    list[i] = L[p];
                    p++;
                } else
                {
                    list[i] = R[q];
                    q++;
                }
                count++;
            }
            return count;
        }

        public static int mergeSort (int[] list, int left, int right)
        {
            int count = 0;
            if (left + 1 < right)
            {
                int mid = (left + right) / 2;
                count += mergeSort(list, left, mid);
                count += mergeSort(list, mid, right);
                count += merge(list, left, mid, right);
            }
            return count;
        }

