        public static int mergeSort(int[] list, int left, int right)
        {
            if (left == right) return 0;
            if (left == right - 1)
            {
                int l = list[left];
                int r = list[right];
                list[left] = l < r ? l : r;
                list[right] = l <= r ? r : l;
                return 1;
            }

            return mergeSort(list, left, (right+left)/2-1)+mergeSort(list,(right+left)/2,right)+merge(list,left,(left+right)/2,right); 
        }

        public static int merge(int[] list, int left, int mid, int right)
        {
            int[] L = new int[mid - left+1];
            int[] R = new int[right - mid + 2];
            int com = 0;

            for(int m=0;m<mid-left;m++)
            {
                L[m] = list[m+left];
            }

            for(int i=0;i<right-mid+1;i++)
            {
                R[i] = list[mid + i];
            }

            L[mid - left] = int.MaxValue;
            R[right - mid + 1] = int.MaxValue;

            int j= 0, k = 0;
            for(int l=left;l<=right;l++)
            {
                if (L[j] <= R[k]) list[l] = L[j++];
                else list[l] = R[k++];
                com++;
            }
            return com;
        }
    }
