	private static int Merge(int[] A, int left, int mid, int right)
	{
		var n1 = mid - left;
		var n2 = right - mid;

		var L = A.Skip(left).Take(n1+1).ToArray();
		var R = new int[n2 + 1];	// for sentinel
		Array.Copy(A, mid, R, 0, n2);
		L[n1] = int.MaxValue;	// Sentinel
		R[n2] = int.MaxValue;

		int i = 0, j=0;

		int cnt = 0;
		for(int k = left; k < right; k++) {
			if(L[i] <= R[j]) {
				A[k] = L[i++];
			} else {
				A[k] = R[j++];
			}
			cnt++;
		}

		return cnt;
