namespace MergeSortApp
{
    class Program
    {
        static void Main(string[] args)
        {
            Console.ReadLine();
            var array = Console.ReadLine()
                .Split(' ')
                .Select(x => int.Parse(x))
                .ToArray();
            var count = 0;
            var sorted = MergeSort(array, 0, array.Length, ref count);
            Console.WriteLine(string.Join(" ", sorted));
            Console.WriteLine(count);
        }

        private static int[] MergeSort(int[] array, int leftIndex, int rightIndex, ref int count)
        {
            var mid = leftIndex + (rightIndex - leftIndex) / 2;
            if (leftIndex == mid)
            {
                return new[] { array[leftIndex] };
            }

            var leftArray = MergeSort(array, leftIndex, mid, ref count);
            var rightArray = MergeSort(array, mid, rightIndex, ref count);
            return Merge(leftArray, rightArray, ref count);
        }

        private static int [] Merge(int[] leftArray, int[] rightArray, ref int count)
        {
            var result = new int[leftArray.Length + rightArray.Length];
            var leftIndex = 0;
            var rightIndex = 0;
            var resultIndex = 0;

            while(leftIndex < leftArray.Length || rightIndex < rightArray.Length)
            {
                count++;
                if (leftIndex == leftArray.Length)
                {
                    result[resultIndex++] = rightArray[rightIndex++];
                    continue;
                }

                if (rightIndex == rightArray.Length)
                {
                    result[resultIndex++] = leftArray[leftIndex++];
                    continue;
                }

                var leftValue = leftArray[leftIndex];
                var rightValue = rightArray[rightIndex];
                if (leftValue < rightValue)
                {
                    result[resultIndex++] = leftArray[leftIndex++];
                }
                else
                {
                    result[resultIndex++] = rightArray[rightIndex++];
                }
            }

            return result;
        }
    }
}

