            _count = 0;
            MergeSort(0, _n);

            StringBuilder sb = new StringBuilder();
            sb.Append(_A[0]);
            foreach (int a in _A.Skip(1)) {
                sb.AppendFormat(" {0}", a);
            }
            sb.AppendFormat("\n{0}\n", _count);
            Console.Write(sb);
        }

        private void MergeSort(int left,int right) {
            if (left + 1 < right) {
                int mid = (left + right) / 2;
                MergeSort(left, mid);
                MergeSort(mid, right);
                Merge(left, mid, right);
            }
        }

        private void Merge(int left,int mid,int right) {
            int n1 = mid - left;
            int n2 = right - mid;

            int[] L = new int[n1 + 1];
            for(int i = 0; i < n1; i++) {
                L[i] = _A[left + i];
            }
            L[n1] = int.MaxValue;

            int[] R = new int[n2 + 1];
            for(int i = 0; i < n2; i++) {
                R[i] = _A[mid + i];
            }
            R[n2] = int.MaxValue;

