            int y = 0;
            for (int i = left; i < right; i++) {
                if (L[x] <= R[y]) {
                    _A[i] = L[x];
                    x++;
                }
                else {
                    _A[i] = R[y];
                    y++;
                }
                _count++;
            }
        }
