using System;

class Merge_Sort {

	static int count = 0;

	public static void Main() {

		int n = int.Parse(Console.ReadLine());
		string[] S_s = Console.ReadLine().Split(' ');
		int[] S = new int[n];
		for(int i = 0; i < n; i++) {
			S[i] = int.Parse(S_s[i]);
		}
		int left = 0, right = n;
		mergeSort(S, left, right);

		string ans = "";
		foreach(int num in S) {
			ans += num.ToString();
			ans += " ";
		}

		ans = ans.TrimEnd();
		Console.WriteLine(ans + "\n{0}", count);

	}

	static void merge(int[] S, int left, int mid, int right) {

		int n1 = mid - left;
		int n2 = right - mid;
		int[] L = new int[n1 + 1];
		int[] R = new int[n2 + 1];

		for(int j = 0; j < n1; j++) {
			L[j] = S[left + j];
		}
		for(int j = 0; j < n2; j++) {
			R[j] = S[mid + j];
		}
		L[n1] = int.MaxValue;
		R[n2] = int.MaxValue;

		for(int k = left, i = 0, j = 0; k < right; k++) {
			if(L[i] <= R[j]) {
				S[k] = L[i];
				count++;
				i++;
			} else {
				S[k] = R[j];
				count++;
				j++;
			}
		}

	}

	static void mergeSort(int[] S, int left, int right) {

		if(left + 1 < right) {
			int mid = (right + left) / 2;
			mergeSort(S, left, mid);
			mergeSort(S, mid, right);
			merge(S, left, mid, right);
		}

	}

}

