namespace AOJ.ALDS
{
    public class MergeSort
    {
        private static int compare;

        private static int[] Sort(int[] array, int left, int right)
        {
            if (left + 1 < right)
            {
                int mid = (left + right) / 2;
                var l_array = Sort(array, left, mid);
                var r_array = Sort(array, mid, right);
                return Merge(l_array, r_array);
            }
            else
            {
                return new int[] { array[left] };
            }
        }

        // 2つの配列をマージする
        private static int[] Merge(int[] a, int[] b)
        {
            int[] ret = new int[a.Length + b.Length];
            int a_cnt = 0;
            int b_cnt = 0;
            for (int i = 0; i < a.Length + b.Length; i++)
            {
                if (a_cnt >= a.Length)
                {
                    ret[i] = b[b_cnt];
                    b_cnt++;
                }
                else if (b_cnt >= b.Length)
                {
                    ret[i] = a[a_cnt];
                    a_cnt++;
                }
                else
                {
                    if (a[a_cnt] <= b[b_cnt])
                    {
                        ret[i] = a[a_cnt];
                        a_cnt++;
                    }
                    else
                    {
                        ret[i] = b[b_cnt];
                        b_cnt++;
                    }
                }
                compare++;
            }

            return ret;
        }

        public static void Main()
        {
            int length = int.Parse(Console.ReadLine());
            int[] array = new int[length];
            var input = Console.ReadLine().Split(' ');
            for (int i = 0; i < length; i++) { array[i] = int.Parse(input[i]); }

            // ソート
            compare = 0;
            var ret = Sort(array, 0, length);

            // 出力
            string output = "";
            for (int i = 0; i < length; i++) { output += " " + ret[i]; }
            output = output.Trim();
            Console.WriteLine(output);
            Console.WriteLine(compare);
        }
    }
}

