			mergeSort(ls, left, mid);
			mergeSort(ls, mid, right);
			merge(ls, left, mid, right);
		}
	} 
	public static void merge(int[] ls, int left, int mid, int right){
		int n1 = mid - left, n2 = right - mid;
		int[] L = new int[n1 + 1], R = new int[n2 + 1];
		for(int i = 0; i < n1; i++) L[i] = ls[left + i];
		for(int i = 0; i < n2; i++) R[i] = ls[mid + i];
		L[n1] = int.MaxValue; R[n2] = int.MaxValue;
		for(int k = left, i = 0, j = 0; k < right; k++) 
			if (L[i] < R[j]){
				ls[k] = L[i++];
				comp++;
			}
			else{
				ls[k] = R[j++];
				comp++;
			}
	}
}

