    public static class Problem {
        public static int MergeSort(this int[] A,int left,int right) {
            int count = 0;
            if (left + 1 < right) {
                int mid = (left + right) / 2;
                count += A.MergeSort(left, mid);
                count += A.MergeSort(mid, right);
                count += A.Merge(left, mid, right);
            }
            return count;
        }

        private static int Merge(this int[] A,int left,int mid,int right) {
            int n1 = mid - left;
            int n2 = right - mid;
            int count = 0;

            int[] L = new int[n1 + 1];
            for(int i = 0; i < n1; i++) {
                L[i] = A[left + i];
            }
            L[n1] = int.MaxValue;

            int[] R = new int[n2 + 1];
            for(int i = 0; i < n2; i++) {
                R[i] = A[mid + i];
            }
            R[n2] = int.MaxValue;

            int x = 0;
            int y = 0;
            for (int i = left; i < right; i++) {
                if (L[x] <= R[y]) {
                    A[i] = L[x];
                    x++;
                }
                else {
                    A[i] = R[y];
                    y++;
                }
                count++;
            }
            return count;
        }
    }

