            StringBuilder sb = new StringBuilder();
            sb.Append(S[0]);
            foreach (int s in S.Skip(1)) {
                sb.AppendFormat(" {0}", s);
            }
            sb.AppendFormat("\n{0}\n", count);
            Console.Write(sb);
        }
    }
