// Runs mergeSort algorithm on a slice single
func mergeSort(slice []int) []int {
	if len(slice) <= 1 {
		return slice
	}
	mid := len(slice) / 2
	left := mergeSort(slice[:mid])
	right := mergeSort(slice[mid:])
	return merge(left, right)
}

// Merges left and right slice into newly created slice
func merge(left, right []int) []int {
	ret := []int{}
	for len(left) > 0 && len(right) > 0 {
		var x int
		// ソート済みのふたつのスライスからより小さいものを選んで追加していく (これがソート処理)
		if right[0] > left[0] {
			x, left = left[0], left[1:]
		} else {
			x, right = right[0], right[1:]
		}
		ret = append(ret, x)
	}
	// 片方のスライスから追加する要素がなくなったら残りは単純に連結できる (各スライスは既にソートされているため)
	ret = append(ret, left...)
	return append(ret, right...)
