func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)
	n, err := nextInt(sc)
	if err != nil {
		panic(err)
	}
	elems, err := nextInts(n, sc)
	if err != nil {
		panic(err)
	}
	sorted, count := mergeSort(elems)
	fmt.Println(strings.Join(isToAs(sorted), " "))
	fmt.Println(count)
}

func mergeSort(elems []int) ([]int, int) {
	length := len(elems)
	if length == 1 {
		return elems, 0
	}
	mid := length / 2
	left, countL := mergeSort(elems[:mid])
	right, countR := mergeSort(elems[mid:])
	sorted, countS := merge(left, right)
	return sorted, (countL + countR + countS)
}

func merge(xs, ys []int) ([]int, int) {
	sorted := make([]int, 0)
	count := 0
	for len(xs) > 0 && len(ys) > 0 {
		if xs[0] < ys[0] {
			sorted = append(sorted, xs[0])
			xs = xs[1:]
		} else {
			sorted = append(sorted, ys[0])
			ys = ys[1:]
		}
		count++
	}
	if len(xs) > 0 {
		sorted = append(sorted, xs...)
		count += len(xs)
	} else if len(ys) > 0 {
		sorted = append(sorted, ys...)
		count += len(ys)
	}
	return sorted, count
}

func nextInt(sc *bufio.Scanner) (int, error) {
	sc.Scan()
	return strconv.Atoi(sc.Text())
}

func nextInts(n int, sc *bufio.Scanner) ([]int, error) {
	ns := make([]int, n)
	for i, _ := range ns {
		x, err := nextInt(sc)
		if err != nil {
			return nil, err
		}
		ns[i] = x
	}
	return ns, nil
}

func isToAs(is []int) []string {
	as := make([]string, len(is))
	for i, _ := range as {
		as[i] = strconv.Itoa(is[i])
	}
	return as
}

