// (sorted ints, compare count)
func mergeSort(xs []int) ([]int, int) {
	n := len(xs)
	if n <= 1 {
		return xs, 0
	}

	mid := n/2
	leftXs, leftCount := mergeSort(xs[:mid])
	rightXs, rightCount := mergeSort(xs[mid:])

	newXs := make([]int, n)
	leftN, rightN := len(leftXs), len(rightXs)
	ind, leftInd, rightInd := 0, 0, 0
	count := 0

	for leftInd < leftN && rightInd < rightN {
		if leftXs[leftInd] < rightXs[rightInd] {
			newXs[ind] = leftXs[leftInd]
			leftInd++
		} else {
			newXs[ind] = rightXs[rightInd]
			rightInd++
		}
		ind++
		count++
	}
	for leftInd < leftN {
		newXs[ind] = leftXs[leftInd]
		ind++
		leftInd++
		count++
	}
	for rightInd < rightN {
		newXs[ind] = rightXs[rightInd]
		ind++
		rightInd++
		count++
	}

	return newXs, leftCount + rightCount + count
}

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Split(bufio.ScanWords)

	n, err := nextInt(sc)
	if err != nil {
		panic(err)
	}

	xs := make([]int, n)
	for i := 0; i < n; i++ {
		x, err := nextInt(sc)
		if err != nil {
			panic(err)
		}
		xs[i] = x
	}

	sortedXs, count := mergeSort(xs)
	fmt.Println(formatInts(sortedXs))
	fmt.Println(count)
}

func formatInts(xs []int) string {
	n := len(xs)
	ss := make([]string, n)
	for i := 0; i < n; i++ {
		ss[i] = strconv.Itoa(xs[i])
	}
	return strings.Join(ss, " ")
}

