func merge(x, y []int) []int {

	// 2つの配列をマージする
	//   格納先を作る
	//   2つの配列の先頭から比較していき,小さい方を新たな格納先へ入れる
	//   どちらかがなくなったら在庫を全部入れる.

	xi := 0
	yi := 0
	arr := make([]int, len(x)+len(y))
	for k := range arr {
		if xi >= len(x) {
			arr[k] = y[yi]
			yi++
		} else if yi >= len(y) {
			arr[k] = x[xi]
			xi++
		} else if x[xi] <= y[yi] {
			arr[k] = x[xi]
			xi++
		} else {
			arr[k] = y[yi]
			yi++
		}
	}
	return arr
}

// 番兵あり
func mergeEx(x, y []int) []int {

	// 2つの配列をマージする
	//   比較用の配列をつくる． xの後ろにyを逆順にするのがミソ
	//   先頭と終端から比較していく．境界に番兵がいるためx,yの終端チェックを
	//   省くことができる
	wa := make([]int, len(x)+len(y))
	copy(wa, x)
	copy(wa[len(x):], reverse(y))

	arr := make([]int, len(x)+len(y))
	i := 0
	j := len(wa) - 1
	for k := 0; k < len(arr); k++ {
		if wa[i] < wa[j] {
			arr[k] = wa[i]
			i++
		} else {
			arr[k] = wa[j]
			j--
		}
	}
	return arr
}
func mergeSort(a []int) []int {
	if len(a) <= 1 {
		return a
	}
	mid := len(a) / 2
	// 左側をソートする
	left := mergeSort(a[0:mid])
	// 右側をソートする
	right := mergeSort(a[mid:])
	// マージする
	return mergeEx(left, right)
}

