func mergeSort(n []int) []int {
	i := len(n) / 2
	if i == 0 {
		return n
	}
	left := mergeSort(n[:i])
	right := mergeSort(n[i:])
	return merge(left, right, []int{})
}

func merge(left, right, merged []int) []int {
	if len(left) == 0 && len(right) == 0 {
		return merged
	}

	if len(left) == 0 {
		count += len(right)
		return append(merged, right...)
	}
	if len(right) == 0 {
		count += len(left)
		return append(merged, left...)
	}

	count++
	if left[0] < right[0] {
		return merge(left[1:], right, append(merged, left[0]))
	}
	return merge(left, right[1:], append(merged, right[0]))
}

