func merge(A []int, left, mid, right int) {
	n1 := mid - left
	n2 := right - mid
	L := make([]int, n1+1)
	R := make([]int, n2+1)
	for i := 0; i < n1; i++ {
		L[i] = A[left+i]
	}
	for i := 0; i < n2; i++ {
		R[i] = A[mid+i]
	}
	L[n1] = 1 << 60
	R[n2] = 1 << 60
	i, j := 0, 0
	for k := left; k < right; k++ {
		if L[i] <= R[j] {
			A[k] = L[i]
			i++
		} else {
			A[k] = R[j]
			j++
		}
	}
}

func sort(A []int, left, right int) int {
	count := 0
	if right-left > 1 {
		mid := (left + right) / 2
		count += sort(A, left, mid)
		count += sort(A, mid, right)
		merge(A, left, mid, right)
		count += right - left
	}
	return count
}

