import sys


class MergeSort(object):

    def __init__(self, a):
        self.a = a
        self.compare = 0

    def merge(self, left, mid, right):
        n1 = mid - left
        n2 = right - mid
        l = self.a[left: mid]
        r = self.a[mid: right]
        l.append(sys.maxsize)
        r.append(sys.maxsize)
        (i, j) = (0, 0)
        for k in range(left, right):
            self.compare += 1
            if l[i] <= r[j]:
                self.a[k] = l[i]
                i += 1
            else:
                self.a[k] = r[j]
                j += 1

    def merge_sort(self, left, right):
        if left + 1 < right:
            mid = (left + right) // 2
            self.merge_sort(left, mid)
            self.merge_sort(mid, right)
            self.merge(left, mid, right)

    def execute_merge_sort(self):
        self.merge_sort(0, len(self.a))
        return self.a


