import sys


def merge(lst, left, mid, right):
    L = lst[left: mid]
    R = lst[mid: right]
    cnt = 0
    for k in range(left, right):
        cnt += 1
        if L or R:
            if not L:
                lst[k] = R.pop(0)
            elif not R:
                lst[k] = L.pop(0)
            elif L[0] <= R[0]:
                lst[k] = L.pop(0)
            else:
                lst[k] = R.pop(0)
    return cnt


def mergeSort(lst, left, right):
    if left + 1 < right:
        mid = (left + right) >> 1
        cnt = mergeSort(lst, left, mid)
        cnt += mergeSort(lst, mid, right)
        return merge(lst, left, mid, right) + cnt
    else:
        return 0


