fn merge_sort<T: Ord>(xs: &mut [T]) -> usize {
    if xs.len() <= 1 {
        return 0;
    }

    let len = xs.len();
    let mid = xs.len() / 2;

    let (sum, mut out) = {
        let (l, r) = xs.split_at_mut(mid);

        let a = merge_sort(l);
        let b = merge_sort(r);
        let mut out = Vec::with_capacity(len);
        unsafe {
            out.set_len(len);
        }
        let c = merge(l, r, &mut out);
        (a + b + c, out)
    };

    for (x, y) in xs.iter_mut().zip(out.iter_mut()) {
        std::mem::swap(x, y);
    }

    sum
}

fn merge<T: Ord>(l: &mut [T], r: &mut [T], out: &mut [T]) -> usize {
    let mut li = 0;
    let mut ri = 0;

    let mut count = 0;
    let mut i = 0;

    while li < l.len() && ri < r.len() {
        if l[li] <= r[ri] {
            std::mem::swap(&mut l[li], &mut out[i]);
            li += 1;
        } else {
            std::mem::swap(&mut r[ri], &mut out[i]);
            ri += 1;
        }
        i += 1;

        count += 1;
    }

    while li < l.len() {
        std::mem::swap(&mut l[li], &mut out[i]);
        li += 1;
        i += 1;
        count += 1;
    }

    while ri < r.len() {
        std::mem::swap(&mut r[ri], &mut out[i]);
        ri += 1;
        i += 1;
        count += 1;
    }

    count
}

