static mut N_COMPARE: i32 = 0;

fn merge_sort(inputs: &mut Vec<i32>, left: usize, right: usize) -> () {
    if left + 1 >= right {
        return ();
    }
    let middle = (left + right) / 2;
    merge_sort(inputs, left, middle);
    merge_sort(inputs, middle, right);
    merge(inputs, left, middle, right)
}

fn merge(inputs: &mut Vec<i32>, left: usize, middle: usize, right: usize) -> () {
    let n1 = middle - left;
    let n2 = right - middle;
    let infinity: i32 = 2 * 10_f32.powi(9) as i32;
    let mut l = inputs[left..(left + n1)].to_vec();
    let mut r = inputs[middle..(middle + n2)].to_vec();
    l.push(infinity);
    r.push(infinity);

    let mut i = 0 as usize;
    let mut j = 0 as usize;
    for k in left..right {
        if l[i] <= r[j] {
            inputs[k] = l[i];
            i += 1;
        } else {
            inputs[k] = r[j];
            j += 1;
        }
        unsafe {
            N_COMPARE += 1;
        }
    }
}

