const BUF_SIZE: usize = 1024;

unsafe fn solve(io: &mut Io) {
    let n = io.ru();
    let mut s = io.c::<u32>(n);
    let c = merge_sort(&mut s);

    s.get(0).map(|s0| io.wn(s0));
    for si in s.iter().skip(1) {
        io.wn(' ');
        io.wn(si);
    }
    io.wn('\n');
    io.w(c);
}

static mut BUF: [u32; 500000] = [0; 500000];
unsafe fn merge_sort(input: &mut [u32]) -> usize {
    unsafe fn inner(input: &mut [u32], left: usize, right: usize) -> usize {
        if left + 1 < right {
            let mid = (left + right) / 2;
            let mut count = inner(input, left, mid) + inner(input, mid, right);

            let mut i = 0;
            let mut j = 0;
            for k in 0.. {
                if i < mid - left {
                    if j < right - mid {
                        if input[left + i] >= input[mid + j] {
                            BUF[k] = input[mid + j];
                            j += 1;
                        } else {
                            BUF[k] = input[left + i];
                            i += 1;
                        }
                    } else {
                        BUF[k] = input[left + i];
                        i += 1;
                    }
                } else {
                    if j < right - mid {
                        BUF[k] = input[mid + j];
                        j += 1;
                    } else {
                        break;
                    }
                }
                count += 1;
            }

            for i in 0..right - left {
                input[left + i] = BUF[i];
            }

            count
        } else {
            0
        }
    }
    let len = input.len();
    inner(input, 0, len)
}

