    let mut l: Vec<i64> = Vec::new();
    let mut r: Vec<i64> = Vec::new();
    for i in left..mid {
        l.push(a[i]);
    }
    for i in mid..right {
        r.push(a[i]);
    }
    l.push(std::i64::MAX);
    r.push(std::i64::MAX);
    let mut i: usize = 0;
    let mut j: usize = 0;
