use std::io;
use std::io::Read;
use std::iter;

fn merge_sort(xs: &mut [usize], left: usize, right: usize) -> usize {
    if left + 1 < right {
        let mid = (left + right) / 2;
        let ncompleft = merge_sort(xs, left, mid);
        let ncompright = merge_sort(xs, mid, right);
        let ncompthis = merge(xs, left, mid, right);
        ncompleft + ncompright + ncompthis
    } else {
        0
    }
}

fn merge(xs: &mut [usize], left: usize, mid: usize, right: usize) -> usize {
    let l: Vec<usize> = xs[left..mid]
        .iter()
        .cloned()
        .chain(iter::once(std::usize::MAX))
        .collect();
    let r: Vec<usize> = xs[mid..right]
        .iter()
        .cloned()
        .chain(iter::once(std::usize::MAX))
        .collect();
    let mut i = 0;
    let mut j = 0;
    let mut ncomp = 0;

    for k in left..right {
        if l[i] <= r[j] {
            xs[k] = l[i].clone();
            i += 1;
        } else {
            xs[k] = r[j].clone();
            j += 1;
        }
        ncomp += 1;
    }

    ncomp
}

