fn mergeSort(S:&mut Vec<usize>,left:usize,right:usize)->usize{
    let mut cnt = 0;
    if left+1 < right{
        let mid = (left + right)/2;
        cnt += mergeSort(S, left, mid);
        cnt += mergeSort(S, mid, right);
        cnt += merge(S,left,mid,right);
    }
    cnt
}

fn merge(S:&mut Vec<usize>,left:usize,mid:usize,right:usize)->usize{
    let mut cnt = 0;
    let mut L = (left..mid).map(|i| S[i]).collect::<Vec<_>>();
    let mut R = (mid..right).map(|i| S[i]).collect::<Vec<_>>();
    let INF = 1_000_100_000;
    L.push(INF);
    R.push(INF);
    let mut i = 0;
    let mut j = 0;
    for k in left..right{
        if L[i] <= R[j]{
            S[k] = L[i];
            i += 1;
        } else {
            S[k] = R[j];
            j += 1
        }
        cnt += 1;
    }
    cnt
}

