      writeln!(stderr(), "Terminated with EOF").unwrap();
      std::process::exit(0);
    }
  }
}

fn merge(vec: &mut Vec<i32>, left: usize, mid: usize, right: usize, cmp_n: &mut i32) {
  let n1 = mid - left;
  let n2 = right - mid;
  let mut l = Vec::with_capacity(n1 + 1);
  let mut r = Vec::with_capacity(n2 + 1);
  for i in 0..n1 {
    l.push(vec[left + i]);
  }
  for i in 0..n2 {
    r.push(vec[mid + i]);
  }
  l.push(std::i32::MAX);
  r.push(std::i32::MAX);
  let (mut i, mut j) = (0, 0);
  for k in left..right {
    *cmp_n += 1;
    if l[i] <= r[j] {
      vec[k] = l[i];
      i += 1;
    }
    else {
      vec[k] = r[j];
      j += 1;
    }
  }
}

fn merge_sort(vec: &mut Vec<i32>, left: usize, right: usize, cmp_n: &mut i32) {
  if left + 1 < right {
    let mid = (left + right) / 2;
    merge_sort(vec, left, mid, cmp_n);
    merge_sort(vec, mid, right, cmp_n);
    merge(vec, left, mid, right, cmp_n);
  }
}

