fn merge(a: &mut [u32], mid: usize) {
    let l: Vec<_> = a[..mid].iter().cloned().collect();
    let r: Vec<_> = a[mid..].iter().cloned().collect();
    let mut i = l.iter().peekable();
    let mut j = r.iter().peekable();
    let max = &&u32::max_value();
    for x in a.iter_mut() {
        *x = if i.peek().unwrap_or(max) <= j.peek().unwrap_or(max) {
            *i.next().unwrap()
        } else{
            *j.next().unwrap()
        }
    }
    assert_eq!(i.next(), None);
    assert_eq!(j.next(), None);
}

fn merge_sort(a: &mut [u32]) -> usize {
    let n = a.len();
    if n >= 2 {
        let mid = n / 2;
        let res = n + merge_sort(&mut a[0..mid]) + merge_sort(&mut a[mid..]);
        merge(a, mid);
        res
    } else {
        0
    }
}

